        #region TrnForm24QSalaryDetails_Load
        private void TrnForm24QSalaryDetails_Load(object sender, EventArgs e)
        {
            int h = Screen.PrimaryScreen.WorkingArea.Height;
            int w = Screen.PrimaryScreen.WorkingArea.Width;
            this.ClientSize = new Size(w, h);
            //
            GC.Collect();
            //
            //-----------------------------------------------------------
            if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2026_27ID)
                lblTitle.Text = "Form " + T_FormNo.F138_24Q + " Salary Details";
            else
                lblTitle.Text = "Form " + T_FormNo.F24Q + " Salary Details";
            //-----------------------------------------------------------                
            txtFinancialYear.Text = TDSMAN.Classes.TDSMAN.T_pFinancialYear;
            txtQuarter.Text = TDSMAN.Classes.TDSMAN.T_pQuarter;
            txtCompany.Text = TDSMAN.Classes.TDSMAN.T_pCompanyName;
            txtTAN.Text= TDSMAN.Classes.TDSMAN.T_pTAN; //-- 2020/06/03
            //ADDED BY @@DHRUB --2015-08-11
            txtFAYearID.Text = TDSMAN.Classes.TDSMAN.T_pFinancialYearId.ToString();
            //
            if (TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.STANDARD_EDITION)
            {
                strExcelActivateButtonCaption = "Add data using Excel";
                btnExcelActivate.Text = strExcelActivateButtonCaption;
                rbnModifyDeductees.Visible = false;
                rbnAddDeductees.Visible = false;
                pnlLine1.Visible = false;
                grpModifyDeductees.Visible = false;
            }
            //-- 2019/05/05
            pnlImportExcelFile.Location = new Point(12, 82);
            //
            ClearControlsHeader();
            //
            //-- 2020/07/01
            ////chkTaxation115BAC.Visible = false;
            ////if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2020_21ID)
            ////    chkTaxation115BAC.Visible = true;
            //-- 2024/04/25
            chkTaxation115BAC.Visible = false;
            chkOptOut115BAC_1A.Visible = false;
            //chkDefaultCheck115BAC.Visible = false;
            if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2020_21ID)
            {
                chkTaxation115BAC.Visible = true;
                chkTaxation115BAC.Appearance = Appearance.Normal;
                chkTaxation115BAC.Text = "Taxation u/s 115BAC(1A)";
                //-- FVU 8.2 2023/08/17
                if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2023_24ID)
                {
                    chkTaxation115BAC.Text = "New Regime";// "Taxation u/s 115BAC(1A)";
                    chkTaxation115BAC.TextAlign = ContentAlignment.MiddleCenter;
                    chkTaxation115BAC.Cursor = Cursors.Default;
                    chkTaxation115BAC.ForeColor = Color.Red;
                    chkTaxation115BAC.AutoCheck = false;
                    chkTaxation115BAC.Checked = true;
                    chkTaxation115BAC.Appearance = Appearance.Button;
                    //chkDefaultCheck115BAC.Visible = true;
                    //chkDefaultCheck115BAC.Location = new Point(chkTaxation115BAC.Location.X, chkTaxation115BAC.Location.Y);
                    //
                    chkOptOut115BAC_1A.Visible = true;
                }
            }
            //--
            txtEmployeeName.Select();
            //
            mskEmployeeFromDate.Text = TdsMan.T_ReturnStartDateFinancialYear(txtFinancialYear.Text);
            mskEmployeeToDate.Text = TdsMan.T_ReturnEndDateFinancialYear(txtFinancialYear.Text);
            //-----------------------------------------------------------
            lblMode.Text = J_Mode.View;
            cmnService.J_StatusButton(this, lblMode.Text);
            //
            BtnAdd_Click(sender, e);
            //
            chkTaxation115BAC.Checked = true;
            //## ANIK 2013/04/26
            if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId == T_FinancialYearID.F2010_11ID ||
                    TDSMAN.Classes.TDSMAN.T_pFinancialYearId == T_FinancialYearID.F2011_12ID)
            {
                lblCaption80CC.Text = "Total Deductible Amount (80CCF)";
            }
            else if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2012_13ID)
            {
                lblCaption80CC.Text = "Total Deductible Amount (80CCG)";
            }
            //##
            if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2013_14ID)
            {
                grpSalaryBreakup.Visible = true;
                grpTDSBreakup.Visible = true;
                //-- 2016/09/22
                grpSuperannuationFund.Visible = true;
                //-- 2017/04/11
                if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2016_17ID)
                {
                    grpRent.Visible = true;
                    grpHouseProperty.Visible = true;
                }
            }
            else
            {
                grpSalaryBreakup.Visible = false;
                grpTDSBreakup.Visible = false;
                //--
                //grpDeductionsUS16.Location = new Point(grpDeductionsUS16.Location.X, grpDeductionsUS16.Location.Y - 82);
                //lblIncomeChargeableDesc.Location = new Point(lblIncomeChargeableDesc.Location.X, lblIncomeChargeableDesc.Location.Y - 82);
                //lblIncomeChargeable.Location = new Point(lblIncomeChargeable.Location.X, lblIncomeChargeable.Location.Y - 82);
                //lblOtherIncomeDesc.Location = new Point(lblOtherIncomeDesc.Location.X, lblOtherIncomeDesc.Location.Y - 82);
                //txtOtherIncome.Location = new Point(txtOtherIncome.Location.X, txtOtherIncome.Location.Y - 82);
