        #region BtnSearchOK_Click
        private void BtnSearchOK_Click(object sender, System.EventArgs e)
        {
            try
            {
                //-------------------------------------------------------------------
                if (ValidateFields() == false) return;
                strCheckFields = "";
                //-------------------------------------------------------------------
                //--- Storing the Criteria Fiels & Values ---------------------------
                //-------------------------------------------------------------------
                //-- SL NO SEARCH 
                //-------------------------------------------------------------------
                if (txtSlNoSearch.Text.Trim() != "")
                    strCheckFields = strCheckFields + "AND COR_TRN_SALARY_DETAILS.SL_NO = " + cmnService.J_ReturnInt32Value(txtSlNoSearch.Text.Trim()) + " ";
                //-------------------------------------------------------------------
                //-- EMPLOYEE NAME SEARCH
                //-------------------------------------------------------------------
                if (txtEmployeeNameSearch.Text.Trim() != "")
                    strCheckFields = strCheckFields + "AND COR_TRN_SALARY_DETAILS.EMPLOYEE_NAME like '%" + cmnService.J_ReplaceQuote(txtEmployeeNameSearch.Text.Trim().ToUpper()) + "%' ";

                // *******************************************************************************
                // *** ADDED BY SHREY KEJRIWAL ON 30/12/2011
                // *******************************************************************************

                //-- EMPLOYEE PAN SEARCH
                if (txtPANSearch.Text.Trim() != "")
                    strCheckFields = strCheckFields + "AND COR_TRN_SALARY_DETAILS.EMPLOYEE_PAN LIKE '%" + cmnService.J_ReplaceQuote(txtPANSearch.Text.Trim().ToUpper()) + "%' ";
                // *******************************************************************************

                //-------------------------------------------------------------------
                //-- DEDUCTED AMOUNT SEARCH
                //-------------------------------------------------------------------
                if (txtTotalDeductedSearch.Text.Trim() != "")
                    strCheckFields = strCheckFields + "AND COR_TRN_SALARY_DETAILS.TOTAL_TDS_DEDUCTED = " + cmnService.J_ReturnDoubleValue(txtTotalDeductedSearch.Text.Trim()) + " ";
                //----------------------------------------------------------------------
                strSQL = strQuery + strCheckFields + "ORDER BY " + strOrderBy;
                //----------------------------------------------------------------------

                lngTempSearchId = lngSearchId;

                if (dsetGridClone != null) dsetGridClone.Clear();
                dsetGridClone = dmlService.J_ShowDataInGrid(ref dgcViewSalaryDetails, strSQL, strMatrix);       //Show Data into the Grid
                if (dsetGridClone == null) return;
                //----------------------------------------------------------------------
                if (dmlService.J_setGridPosition(ref dgcViewSalaryDetails, dsetGridClone, lngTempSearchId) == false)
                {
                    txtSlNoSearch.Select();
                    return;
                }
                //----------------------------------------------------------------------
                lblSearchMode.Text = J_Mode.General;
                //----------------------------------------------------------------------
                grpSearch.Visible = false;
                //----------------------------------------------------------------------
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

