        #region btnBrowse_Click
        private void btnBrowse_Click(object sender, EventArgs e)
        {
            if (rbnCSV.Checked == true)
            {
                strFVUPath = cmnService.J_OpenFileDialog("CSV File | *.csv", "Excel File | *.csv", "Choose the CSV File to import");
            }
            else
            {
                if (TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_EDITION || TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_LITE_EDITION || TDSMAN.Classes.TDSMAN.T_pEditionType == T_EDITION_TYPE.ENTERPRISE_ULTIMATE_EDITION)
                    strFVUPath = cmnService.J_OpenFileDialog("Excel File | *.xlsx", "Excel File | *.xlsx", "Choose the Excel File to import");
                else
                    strFVUPath = cmnService.J_OpenFileDialog("Excel File | *.xls; *.xlsx", "Excel File | *.xls; *.xlsx", "Choose the Excel File to import");
            }
            //--
            if (strFVUPath != "")
            {
                txtExcelPath.Text = strFVUPath;
                btnCreateBlankExcelFile.Enabled = false;
                btnCreateBlankExcelFile.BackColor = Color.LightGray;
            }
            else
            {
                txtExcelPath.Text = strFVUPath;
                btnCreateBlankExcelFile.Enabled = true;
                btnCreateBlankExcelFile.BackColor = Color.Lavender;
            }
        }
        #endregion

        #region btnCreateBlankExcelFile_Click
        private void btnCreateBlankExcelFile_Click(object sender, EventArgs e)
        {
            try
            {
                //--------------------------------------------------------------------------------------------------
                string strExcelFileName = "";           //-- FOR EXCEL FILE NAME INTO APPLICATION PATH
                string strOutputExcelFileName = "";     //-- FOR OUTPUT EXCEL FILE NAME INTO SELECTED PATH BY USER 
                string strExcelFieldAsciiAfterZ = "";   //--
