                            System.IO.File.Copy(strSourceFile, Path.Combine(strDestFilePath, strDestFile + ".xls"), true);

                        }
                        else
                        {
                            //File.Copy(Path.Combine(strSourcePath, strExcelFileName), Path.Combine(strDestFilePath, strDestFile + ".xls"));
                            File.Copy(Path.Combine(strSourcePath, strExcelFileName), Path.Combine(strDestFilePath, strDestFile + strExtension));
                        }
                    }
                    //--
                    this.Refresh();
                    //--
                    this.Cursor = Cursors.Default;
                    //--
                    //--
                    //------------------------------------------------------------------
                    //CHECK IF FILE IS CREATED OR NOT
                    //------------------------------------------------------------------
                    if (cmnService.J_IsFileExist(Path.Combine(strDestFilePath, strDestFile + strExtension)) == true)
                    {
                        this.Cursor = Cursors.Default;
                        cmnService.J_UserMessage("Blank File Created at " + Path.Combine(strDestFilePath, strDestFile + strExtension));
                        System.Diagnostics.Process.Start(Path.Combine(strDestFilePath, strDestFile + strExtension));
                    }
                    else
                    {
                        this.Cursor = Cursors.Default;
                        cmnService.J_UserMessage("Blank File Creation Failed");
                    }
                    //--
                }
                else
                    cmnService.J_UserMessage("Destination Folder not selected");
            }
            catch (Exception err_handler)
            {
                cmnService.J_UserMessage("Excel file creation failed");
                return;
            }
        }
        #endregion

        #region btnValidate_Click
        private void btnValidate_Click(object sender, EventArgs e)
        {
            //-- Added by Abhishek Dey On 02/11/2018 --
            if (rbnModifyDeductees.Checked == true)
            {
                if (rbnBulkDeletion.Checked == true)
                {
                    //--
                    #region Variable Declaretion

                    string ExcelFilePath = "";
                    int intIncrement = 0;

                    // SALARY DETAILS
                    string strSDSerialNo = string.Empty;
                    string strEmployeePan = string.Empty;
                    string strEmployeeName = string.Empty;
                    string strTotalTaxDeductedAmount = string.Empty;

                    #endregion

                    #region Initialize Variable
                    // SALARY DETAILS
                    strSDSerialNo = "[Serial No]";
                    strEmployeePan = "[Employee Pan]";
                    strEmployeeName = "[Employee Name]";
                    strTotalTaxDeductedAmount = "[Total Tax Deducted]";

                    string ExcelFileName = "EXPORTED_SD_DATA_BULK_DELETION";

                    long lngTotalEmployeeNo = 0;
                    #endregion
                    //-- Added By Abhishek Dey On 29/10/2018 --
                    #region T_tblTEMP_DUMP_EXCEL_SD
                    // DROP TABLE IF EXISTS
                    if (dmlService.J_IsDatabaseObjectExist("" + TDSMAN.Classes.TDSMAN.T_tblTEMP_DUMP_EXCEL_SD + "") == true)
                    {
                        strSQL = "DROP TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DUMP_EXCEL_SD + "";
                        dmlService.J_ExecSql(strSQL);
                    }
                    //
                    // CREATE TABLE
                    #region CREATE TABLE T_tblTEMP_DUMP_EXCEL_SD
                    if (dmlService.J_IsDatabaseObjectExist("" + TDSMAN.Classes.TDSMAN.T_tblTEMP_DUMP_EXCEL_SD + "") == false)
                    {
                        strSQL = "CREATE TABLE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DUMP_EXCEL_SD + " (" +
                                               cmnService.J_GetDataType("DUMP_ID", J_Identity.YES) + @", 
                                       " + cmnService.J_GetDataType("TRN_SALARY_DETAILS_ID", J_ColumnType.Integer) + @",
                                       " + cmnService.J_GetDataType("SD_SL_NO", J_ColumnType.Char) + @",
                                       " + cmnService.J_GetDataType("EMPLOYEE_PAN", J_ColumnType.String) + @",
                                       " + cmnService.J_GetDataType("EMPLOYEE_NAME", J_ColumnType.String) + @",
                                       " + cmnService.J_GetDataType("TAX_DEDUCTED_AMOUNT", J_ColumnType.String) + @",
                                       " + cmnService.J_GetDataType("CONCAT_COLUMNS", J_ColumnType.String, 255) + @")";

                        //"                  DUMP_ID COUNTER," +
                        //"                  SD_SL_NO               NUMBER  DEFAULT 0," +
                        //"                  EMPLOYEE_PAN           TEXT(50) DEFAULT \"\"," +
                        //"                  EMPLOYEE_NAME          TEXT(255) DEFAULT \"\"," +
                        //"                  TAX_DEDUCTED_AMOUNT    MONEY   DEFAULT 0," +
                        //"                  CONCAT_COLUMNS         TEXT(255) DEFAULT \"\")";

                        dmlService.J_ExecSql(strSQL);
                    }
                    #endregion
                    //
                    // INSERT DATA
                    #region INSERT
                    strSQL = " INSERT INTO " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DUMP_EXCEL_SD + "(TRN_SALARY_DETAILS_ID, SD_SL_NO, EMPLOYEE_PAN, EMPLOYEE_NAME, TAX_DEDUCTED_AMOUNT) ";
                    strSQL = strSQL + @" SELECT TRN_SALARY_DETAILS_ID ," +
                                    "        SL_NO AS " + strSDSerialNo + "," +
                                    "        EMPLOYEE_PAN AS " + strEmployeePan + "," +
                                    "        EMPLOYEE_NAME AS " + strEmployeeName + "," +
                                             cmnService.J_SQLDBFormat("TOTAL_TAX_DEDUCTED_AMOUNT", J_SQLColFormat.ConvertToString) + " AS " + strTotalTaxDeductedAmount + " " + //-- Modified By Abhishek Dey On 05/11/2018 --
                                                                                                                                                                                //"        TOTAL_TAX_DEDUCTED_AMOUNT AS " + strTotalTaxDeductedAmount + " " +
                                    "  FROM  COR_TRN_SALARY_DETAILS " +
                                    "  WHERE BATCH_HEADER_ID = " + lngBatchId + " " +
                                    "  AND   IMPORT_FLAG     = 1 ";

                    if (cmnService.J_ReturnInt64Value(txtFAYearID.Text.Trim()) >= T_FinancialYearID.F2007_08ID)
                    {
                        strSQL = strSQL + @" AND MODE <> '" + T_CorrectionMode.Form26A_27BA + "' ";
                    }

                    strSQL = strSQL + @" ORDER BY SL_NO ";
                    #endregion


                    dmlService.J_ExecSql(strSQL);

                    // UPDATE COLUMN CONCAT
                    #region UPDATE
                    strSQL = @" UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_DUMP_EXCEL_SD +
                                     "    SET CONCAT_COLUMNS  = " + cmnService.J_SQLDBFormat(cmnService.J_SQLDBFormat("SD_SL_NO", J_SQLColFormat.ConvertToNumeric), J_SQLColFormat.ConvertToString) +
                                                                " + EMPLOYEE_PAN " +
                                                                " + " + cmnService.J_SQLDBFormat(cmnService.J_SQLDBFormat("TAX_DEDUCTED_AMOUNT", J_SQLColFormat.ConvertToMoney), J_SQLColFormat.ConvertToString);

                    dmlService.J_ExecSql(strSQL);
                    #endregion


                    #endregion

                }
            }
            //--
            prgBar.Value = 0;
            if (ValidateFields() == false) return;
            //--
            if (rbnExcel.Checked == true)
            {
                if (cmnService.J_UserMessage("Proceed with excel sheet validation??", MessageBoxButtons.YesNo) == DialogResult.No)
                    return;
            }
            else if (rbnCSV.Checked == true)
            {
                if (cmnService.J_UserMessage("Proceed with CSV sheet validation??", MessageBoxButtons.YesNo) == DialogResult.No)
                    return;
            }
            //--
            this.Cursor = Cursors.WaitCursor;
            //--
            string strConnectionString = "";

            if (rbnExcel.Checked == true)
            {
                //MAKING CONNECTION TO THE EXCEL FILE
                if (Path.GetExtension(txtExcelPath.Text.Trim().ToLower()) == ".xls")
                    strConnectionString = "Provider=Microsoft.Jet.OLEDB.4.0;Data Source=" + txtExcelPath.Text + ";Extended Properties=\"Excel 8.0;HDR=Yes;IMEX=1\"";
                else if (Path.GetExtension(txtExcelPath.Text.Trim().ToLower()) == ".xlsx")
                    strConnectionString = "Provider=Microsoft.ACE.OLEDB.12.0;Data Source=" + txtExcelPath.Text + ";Extended Properties=\"Excel 12.0 Xml;HDR=Yes;IMEX=1\"";

                con = new OleDbConnection(strConnectionString);
                //                
                con.Open();
                //--
                if (CheckExcelStructure(txtExcelPath.Text) == false)
                {
                    this.Cursor = Cursors.Default;
                    cmnService.J_UserMessage("Selected Excel file is invalid");
                    prgBar.Value = 0;
                    btnSelectExcelPath.Select();
                    return;
                }
            }
            prgBar.Value = prgBar.Value + 5;
            this.Refresh();
            //--
            lblProgressDisplayMessage.Visible = true;
            lblProgressDisplayMessage.Text = "Process Started";
            //--
            //
            prgBar.Value = prgBar.Value + 5;
            this.Refresh();
            // CREATE TEMP TABLES        
            if (CREATE_TEMP_TABLES() == false)
            {
                cmnService.J_UserMessage("Temporary Tables Not created", MessageBoxIcon.Exclamation);
                this.Cursor = Cursors.Default;
                prgBar.Value = 0;
                return;
            }
            prgBar.Value = prgBar.Value + 5;
            this.Refresh();
            // GET DATA FROM EXCEL ACCESS       
            //
            lblProgressDisplayMessage.Visible = true;
            lblProgressDisplayMessage.Text = "Transferring Data";
            //
            if (rbnExcel.Checked == true)
            {
                //start do work
                if (GET_DATA_FROM_EXCEL() == false)
                {
                    cmnService.J_UserMessage(strErrorMessage);
                    this.Cursor = Cursors.Default;
                    prgBar.Value = 0;
                    return;
                }
            }
            else if(rbnCSV.Checked == true)
            {
                if (GET_DATA_FROM_CSV() == false)
                {
                    cmnService.J_UserMessage(strErrorMessage);
                    this.Cursor = Cursors.Default;
                    prgBar.Value = 0;
                    return;
                }
            }
            //--
            prgBar.Value = prgBar.Value + 5;
            this.Refresh();
            //
            // VALIDATE DATA     
            lblProgressDisplayMessage.Visible = true;
            lblProgressDisplayMessage.Text = "Validation Started";
            //
            if (rbnExcel.Checked == true)
            {
                if (VALIDATE_DATA_EXCEL() == false)
                {
                    cmnService.J_UserMessage("Data Validation failed", MessageBoxIcon.Error);
                    this.Cursor = Cursors.Default;
                    prgBar.Value = 0;
                    return;
                }
            }
            else if(rbnCSV.Checked==true)
            {
                if (VALIDATE_DATA_CSV() == false)
                {
                    cmnService.J_UserMessage("Data Validation failed", MessageBoxIcon.Error);
                    this.Cursor = Cursors.Default;
                    prgBar.Value = 0;
                    return;
                }                
            }
            prgBar.Value = prgBar.Value + 5;
            this.Refresh();
            //--
            if (rbnCSV.Checked==true)
            {
                if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(*) FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ERR_VALIDATION + ""))) > 0)
                {
                    if (WRITE_ERROR_HTML(txtExcelPath.Text) == false)
                    {
                        cmnService.J_UserMessage("Writing Error File failed", MessageBoxIcon.Error);
                        this.Cursor = Cursors.Default;
                        prgBar.Value = 0;
                        return;
                    }
                    prgBar.Value = prgBar.Value + 5;
                    //
                    prgBar.Value = 100;
                    this.Refresh();
                    this.Cursor = Cursors.Default;
                    //--
                    cmnService.J_UserMessage("CSV File Validation failed \n Now it will open the error (HTML) file.", MessageBoxIcon.Exclamation);
                    //--
                    prgBar.Value = 0;
                    if (File.Exists(Path.Combine(Path.GetDirectoryName(txtExcelPath.Text), Path.GetFileNameWithoutExtension(txtExcelPath.Text) + ".htm")) == true)
                    {
                        System.Diagnostics.Process.Start(Path.Combine(Path.GetDirectoryName(txtExcelPath.Text), Path.GetFileNameWithoutExtension(txtExcelPath.Text) + ".htm"));
                    }
                    //-- 
                    return;
                }
            }
            else
            {
                if (DELETE_WORKSHEET(txtExcelPath.Text, strErrorWorksheetName) == false)
                {
                    cmnService.J_UserMessage("Error Sheet Deletion failed", MessageBoxIcon.Error);
                    this.Cursor = Cursors.Default;
                    prgBar.Value = 0;
                    return;
                }
                //--
                if (DELETE_WORKSHEET(txtExcelPath.Text, strNewDeducteeWorkSheetName) == false)
                {
                    cmnService.J_UserMessage("New Deductee Sheet Deletion failed", MessageBoxIcon.Error);
                    this.Cursor = Cursors.Default;
                    prgBar.Value = 0;
                    return;
                }
                prgBar.Value = prgBar.Value + 5;
                this.Refresh();
                //--
                lblProgressDisplayMessage.Visible = true;
                lblProgressDisplayMessage.Text = "New Worksheet created";
                //
                //--
                if (CREATE_NEW_WORKSHEET(txtExcelPath.Text) == false)
                {
                    cmnService.J_UserMessage("Error Sheet Creation failed", MessageBoxIcon.Error);
                    this.Cursor = Cursors.Default;
                    prgBar.Value = 0;
                    return;
                }
                prgBar.Value = prgBar.Value + 5;
                this.Refresh();
                //--
                if (WRITE_ERROR_WORKSHEET_SD(txtExcelPath.Text) == false)
                {
                    cmnService.J_UserMessage("Writing Error Sheet failed", MessageBoxIcon.Error);
                    this.Cursor = Cursors.Default;
                    prgBar.Value = 0;
                    return;
                }
                //--                
                if (chkColorCodingExcelsheet.Checked == true)
                {
                    //
                    lblProgressDisplayMessage.Visible = true;
                    lblProgressDisplayMessage.Text = "EXCEL file coloring";
                    //
                    if (COLOR_ERROR_CELLS(txtExcelPath.Text) == false)
                    {
                        cmnService.J_UserMessage("Coloring Error Cells failed", MessageBoxIcon.Exclamation);
                        this.Cursor = Cursors.Default;
                        prgBar.Value = 0;
                        return;
                    }
                }
            }
            //--
            //Delete_TMP_Files(txtExcelPath.Text);
            lblProgressDisplayMessage.Visible = true;
            lblProgressDisplayMessage.Text = "Temporary files deleted";
            //--
            lblProgressDisplayMessage.Visible = false;
            //--
            //--
            if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT COUNT(*) FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ERR_VALIDATION + ""))) == 0)
            {
                if (DELETE_WORKSHEET(txtExcelPath.Text, strErrorWorksheetName) == false)
                    this.Cursor = Cursors.Default;
                //--
                for (int i = prgBar.Minimum; i <= prgBar.Maximum; i++)
                {
                    prgBar.PerformStep();
                }
                this.Cursor = Cursors.Default;

                //con.Close();
                if (rbnExcel.Checked == true)
                    cmnService.J_UserMessage("Excel File Validation is completed \n     Proceed to Import ", MessageBoxIcon.Information);
                else if (rbnCSV.Checked == true)
                    cmnService.J_UserMessage("CSV File Validation is completed \n     Proceed to Import ", MessageBoxIcon.Information);
                prgImportBar.Value = 0;
            }
            else
            {
                for (int i = prgBar.Minimum; i <= prgBar.Maximum; i++)
                {
                    prgBar.PerformStep();
                }
                this.Cursor = Cursors.Default;

                con.Close();

                //cmnService.J_UserMessage("Excel File Validation failed \n Check the <Validation Error> Sheet of the Excel file ", MessageBoxIcon.Exclamation);
                if (cmnService.J_UserMessage("Excel File Validation failed \n Do you want to open the Excel file ?", MessageBoxButtons.YesNo, MessageBoxIcon.Exclamation) == DialogResult.Yes)
                {
                    if (File.Exists(txtExcelPath.Text) == true)
                    {
                        System.Diagnostics.Process.Start(txtExcelPath.Text);
                    }
                }
                prgBar.Value = 0;
                return;
            }
            //--
            //--
            if (LOAD_IMPORT_INTERFACE() == false)
            {
                cmnService.J_UserMessage("Loading Import Interface failed", MessageBoxIcon.Error);
                this.Cursor = Cursors.Default;
                prgBar.Value = 0;
                return;
            }
            //--
            prgBar.Value = 0;
            //--
            if (rbnExcel.Checked == true)                
                lblTitle.Text = "Excel Import";
            else if (rbnExcel.Checked == true)
                lblTitle.Text = "CSV Import";
            //--
            //-- Added By Abhishek Dey On 22/11/2018 --
            if (rbnModifyDeductees.Checked == true && rbnBulkDeletion.Checked == true)
            {
                lblMessage.Visible = true;
                lblMessage.Location = new Point(299, 19);
                //
                strSQL = @"SELECT COUNT(*) AS TOTAL_COUNT, 
                                       SUM(TOTAL_TAX_DEDUCTED)  AS TOTAL_TDS
                                FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SD_DELETE;

                DataSet dsCount = new DataSet();
                dsCount = dmlService.J_ExecSqlReturnDataSet(strSQL);
                //
                lblMessage.Text = "No of records : " + dsCount.Tables[0].Rows[0]["TOTAL_COUNT"].ToString() + "        Total TDS : " + string.Format("{0:0.00}", Convert.ToDouble(dsCount.Tables[0].Rows[0]["TOTAL_TDS"].ToString()));
            }
            else
                lblMessage.Visible = false;
            //-----------------------------------------
        }
        #endregion 

