        #region dgcViewSalaryDetails_Click
        private void dgcViewSalaryDetails_Click(object sender, EventArgs e)
        {
            //Added by Indrajit on 04-03-2013
            //if (dsetGridClone.Tables[0].Rows.Count == 0) return;
            if (dgcViewSalaryDetails.CurrentRow == null) return;

            if (Convert.ToInt64(dgcViewSalaryDetails.CurrentRow.Index) < 0)
            {
                BtnAdd.Focus();
                return;
            }

            if (lblMode.Text != J_Mode.Edit)
                lngSearchId = Convert.ToInt64(dgcViewSalaryDetails.Rows[dgcViewSalaryDetails.CurrentRow.Index].Cells[0].Value);

            if (lngSearchId > 0)
            {
                if (lblMode.Text == J_Mode.Add)
                {
                    //
                    BtnEdit.Enabled = true;
                    BtnEdit.BackColor = Color.Lavender;
                    //
                    BtnDelete.Enabled = true;
                    BtnDelete.BackColor = Color.Lavender;


                    strSQL = "SELECT MODE FROM COR_TRN_SALARY_DETAILS WHERE TRN_SALARY_DETAILS_ID = " + lngSearchId;
                    //----------------------------------
                    //-- ADDED BY DHRUB @@2015-08-21
                    //----------------------------------
                    string strQueryString = "SELECT PAN_UPDATION_INDICATOR FROM COR_TRN_SALARY_DETAILS WHERE TRN_SALARY_DETAILS_ID = " + lngSearchId;
                    //--------------------------------------------------------------------------------------------------
                    //-- MODIFIED BY @@DHRUB--2015-08-20 TO RESTORE WHEN
                    //--------------------------------------------------------------------------------------------------
                    //-- MODE - > DELETE
                    //-- PAN_UPDATE_INDICATOR - > 1
                    //--------------------------------------------------------------------------------------------------
                    if (Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)) == T_CorrectionMode.Delete ||
                        Convert.ToInt32(dmlService.J_ExecSqlReturnScalar(strQueryString)) == T_UPDATION_INDICATOR.ON)
                        BtnDelete.Text = T_DeleteRestoreText.Restore;
                    else
                        BtnDelete.Text = T_DeleteRestoreText.Delete;
                }
            }
            else
            {
                BtnEdit.Enabled = false;
                BtnEdit.BackColor = Color.LightGray;
            }

        }
        #endregion

        #region dgcViewSalaryDetails_KeyDown
        private void dgcViewSalaryDetails_KeyDown(object sender, KeyEventArgs e)
        {
            if (dgcViewSalaryDetails.CurrentRow.Index < 0) return;

            lngSearchId = Convert.ToInt64(dgcViewSalaryDetails.Rows[dgcViewSalaryDetails.CurrentRow.Index].Cells[0].Value);

            if (e.KeyCode == Keys.Enter) dgcViewSalaryDetails_DoubleClick(sender, e);

            if (e.KeyCode == Keys.Delete) BtnDelete_Click(sender, e);

        }
        #endregion

