        #region Shortfall_TextChanged
        private void Shortfall_TextChanged(object sender, EventArgs e)
        {

            //Added by Shrey Kejriwal on 03-04-2015
            if (blnShowRecord == true) return;

            //lblShortfall.Text = string.Format("{0:0.00}", (cmnService.J_ReturnDoubleValue(lblTaxPayable.Text) - cmnService.J_ReturnDoubleValue(txtTotalTDSDedcuted.Text)));
            ////lblShortfall.Text = string.Format("{0:0.00}", (cmnService.J_ReturnDoubleValue(lblTaxPayable.Text) - cmnService.J_ReturnDoubleValue(lblTotalBreakupTdsTcs.Text)));
            //-- 2016/09/22
            if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2013_14ID)
            {
                lblTotalAmountOfTAX.Text = string.Format("{0:0.00}", cmnService.J_ReturnDoubleValue(txtTotalTDSDedcuted.Text) + cmnService.J_ReturnDoubleValue(txtTaxSuperannuationFund.Text));
                ////////lblShortfall.Text = string.Format("{0:0.00}", (cmnService.J_ReturnDoubleValue(lblTaxPayable.Text) - cmnService.J_ReturnDoubleValue(lblTotalAmountOfTAX.Text)));
                ////lblShortfall.Text = string.Format("{0:0.00}", (cmnService.J_ReturnDoubleValue(lblTaxPayable.Text) - cmnService.J_ReturnDoubleValue(lblTotalBreakupTdsTcs.Text)));
                //////-- 2025/01/03
                ////if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2024_25ID)
                ////    lblShortfall.Text = string.Format("{0:0.00}", (cmnService.J_ReturnDoubleValue(lblTaxPayable.Text) - cmnService.J_ReturnDoubleValue(lblTotalBreakupTdsTcs.Text)));// - cmnService.J_ReturnDoubleValue(lblTotalAmountOfTAX.Text) - cmnService.J_ReturnDoubleValue(txtUs192_2B.Text)));
                if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2024_25ID)
                {
                    lblTotalBreakupTdsTcs.Text = string.Format("{0:0.00}", cmnService.J_ReturnDoubleValue(txtTotalTaxDeductedAmt.Text) + cmnService.J_ReturnDoubleValue(txtPreviousTaxDeductedAmt.Text) + cmnService.J_ReturnDoubleValue(txtUs192_2B.Text));
                    //lblShortfall.Text = string.Format("{0:0.00}", (cmnService.J_ReturnDoubleValue(lblTaxPayable.Text) - cmnService.J_ReturnDoubleValue(txtTotalTaxDeductedAmt.Text) - cmnService.J_ReturnDoubleValue(txtPreviousTaxDeductedAmt.Text) - cmnService.J_ReturnDoubleValue(txtUs192_2B.Text)));
                    lblShortfall.Text = string.Format("{0:0.00}", (cmnService.J_ReturnDoubleValue(lblTaxPayable.Text) - cmnService.J_ReturnDoubleValue(lblTotalBreakupTdsTcs.Text)));// - cmnService.J_ReturnDoubleValue(txtPreviousTaxDeductedAmt.Text) - cmnService.J_ReturnDoubleValue(txtUs192_2B.Text)));
                }
                else
                    lblShortfall.Text = string.Format("{0:0.00}", (cmnService.J_ReturnDoubleValue(lblTaxPayable.Text) - cmnService.J_ReturnDoubleValue(lblTotalAmountOfTAX.Text)));
            }
            //Added by Shrey Kejriwal on 03-04-2015
            //Copying TDS amount to Current Employer's TDS when Previous Employer's TDS is zero
            //if (cmnService.J_ReturnDoubleValue(txtPreviousTaxDeductedAmt.Text) == 0)
            //    txtTotalTaxDeductedAmt.Text = string.Format("{0:0.00}", (cmnService.J_ReturnDoubleValue(txtTotalTDSDedcuted.Text)));

        }
        #endregion

