        #region lstDeducteeHelp_Click
        private void lstDeducteeHelp_Click(object sender, EventArgs e)
        {
            //long lngEmployeeId = Convert.ToInt32(Support.GetItemData(lstDeducteeHelp, lstDeducteeHelp.SelectedIndex));

            //txtEmployeePAN.Text = cmnService.J_Mid(lstDeducteeHelp.Text.Trim(), 32, lstDeducteeHelp.Text.Length - 36);
            if (TDSMAN.Classes.TDSMAN.T_ShareReferenceNoF24Q == true) //-- 2020/06/03
            {
                //////txtEmpRefNo.Text = cmnService.J_Right(lstDeducteeHelp.Text, 9).Trim();
                //////txtDeducteePAN.Text = cmnService.J_Left(cmnService.J_Right(lstDeducteeHelp.Text, 19 + txtEmpRefNo.Text.Length), 10).Trim();
                //////txtDeducteeName.Text = cmnService.J_Mid(lstDeducteeHelp.Text, 0, (lstDeducteeHelp.Text.Length - 31 + txtEmpRefNo.Text.Length)).Trim();
                txtEmpRefNo.Text = cmnService.J_Right(lstDeducteeHelp.Text.Trim(), 10).Trim();
                txtEmployeePAN.Text = cmnService.J_Left(cmnService.J_Right(lstDeducteeHelp.Text.Trim(), 30).Trim(), 10).Trim();
                txtEmployeeName.Text = cmnService.J_Left(lstDeducteeHelp.Text.Trim(), 30).Trim();
            }
            else
            {
                txtEmployeePAN.Text = cmnService.J_Right(lstDeducteeHelp.Text.Trim(), 10).Trim();
                txtEmployeeName.Text = cmnService.J_Mid(lstDeducteeHelp.Text, 0, (lstDeducteeHelp.Text.Length - 10)).Trim();
            }
            //--
            //string strCategory = cmnService.J_Right(lstDeducteeHelp.Text, 3).Trim();
            //txtEmployeePAN.Text = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT EMPLOYEE_PAN FROM COR_TRN_SALARY_DETAILS WHERE "));
            string strCategory = Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT EMPLOYEE_CATEGORY " +
                                                 "FROM  COR_TRN_SALARY_DETAILS " +
                                                 "WHERE EMPLOYEE_NAME ='" + cmnService.J_ReplaceQuote(txtEmployeeName.Text) + "' " +
                                                 "AND   EMPLOYEE_PAN  ='" + cmnService.J_ReplaceQuote(txtEmployeePAN.Text) + "'"));

            if (strCategory == "G")
                cmbEmployeeCategory.Text = T_EmployeeCategory.General;
            else if (strCategory == "W")
                cmbEmployeeCategory.Text = T_EmployeeCategory.Woman;
            else if (strCategory == "S")
                cmbEmployeeCategory.Text = T_EmployeeCategory.SeniorCitizen;
            else if (strCategory == "O")
                cmbEmployeeCategory.Text = T_EmployeeCategory.SuperSeniorCitizen;
            else
                cmbEmployeeCategory.Text = "";


            //txtEmployeeName.Text = cmnService.J_Mid(lstDeducteeHelp.Text, 0, (lstDeducteeHelp.Text.Length - 14)).Trim();

            lstDeducteeHelp.Visible = false;
            //-- 2019/05/26
            if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2018_19ID)
                txtGSSec17_1.Select();
            else
                txtTotalSalaryBalance.Select();
        }
        #endregion

        #region lstDeducteeHelp_KeyPress
        private void lstDeducteeHelp_KeyPress(object sender, KeyPressEventArgs e)
        {
            if (Convert.ToInt64(e.KeyChar) == 13)
                lstDeducteeHelp_Click(sender, e);
            else if (Convert.ToInt64(e.KeyChar) == 27)
            {
                lstDeducteeHelp.Visible = false;
                txtEmployeeName.Select();
            }
        }
        #endregion

        #region txtEmployeeName_TextChanged
        private void txtEmployeeName_TextChanged(object sender, EventArgs e)
        {
            IDataReader drdShowDeducteeHelp = null;
            //--
            string strSQLShowHelpDeductee = "";
            try
            {
                if (txtEmployeeName.Text.Trim() == "")
                {
                    lstDeducteeHelp.Visible = false;
                    return;
                }

                if (blnShowHelp == false)
                    return;
                //-----------------------
                //string strSQLShowHelpDeductee = "SELECT TOP 10 EMPLOYEE_NAME," +
                //            "                           EMPLOYEE_PAN," +
                //            "                           EMPLOYEE_CATEGORY " +
                //            "                   FROM    COR_TRN_SALARY_DETAILS " +
                //            "                   WHERE  EMPLOYEE_NAME LIKE '" + cmnService.J_ReplaceQuote(txtEmployeeName.Text) + "%' " +
                //            "                   AND    BATCH_HEADER_ID    = " + lngBatchId + " " +
                //            "                   GROUP BY EMPLOYEE_PAN, EMPLOYEE_NAME, EMPLOYEE_CATEGORY " +
                //            "                   ORDER BY EMPLOYEE_NAME";

                //string strSQLShowHelpDeductee = @"SELECT  TOP 10 SD.NAME,
                //                                             SD.PAN
                //                                FROM (
                //                                SELECT DEDUCTEE_NAME AS NAME, 
                //                                       DEDUCTEE_PAN         AS PAN
                //                                FROM   COR_TRN_DEDUCTEE_DETAILS 
                //                                WHERE  DEDUCTEE_NAME LIKE '" + cmnService.J_ReplaceQuote(txtEmployeeName.Text) + "%' " +
                //                                       @"AND BATCH_HEADER_ID = " + lngBatchId + " " +
                //                               @"GROUP  BY DEDUCTEE_NAME, 
                //                                          DEDUCTEE_PAN
                //                                UNION
                //                                SELECT  EMPLOYEE_NAME AS NAME, 
                //                                        EMPLOYEE_PAN AS PAN
                //                                FROM   COR_TRN_SALARY_DETAILS 
                //                                WHERE  EMPLOYEE_NAME LIKE '" + cmnService.J_ReplaceQuote(txtEmployeeName.Text) + "%' " +
                //                                      @"AND BATCH_HEADER_ID = " + lngBatchId + " " +
                //                               @"GROUP  BY EMPLOYEE_PAN, 
                //                                          EMPLOYEE_NAME) AS SD
                //                                ORDER  BY SD.NAME";
                if (TDSMAN.Classes.TDSMAN.T_ShareReferenceNoF24Q == true)
                {
                    strSQLShowHelpDeductee = @"SELECT  TOP 10 SD.NAME,
                                                             SD.PAN,
                                                             SD.EMPLOYEE_SERIAL_NO
                                                FROM (
                                                SELECT DEDUCTEE_NAME AS NAME, 
                                                       DEDUCTEE_PAN         AS PAN, 
                                                        EMPLOYEE_SERIAL_NO AS EMPLOYEE_SERIAL_NO
                                                FROM   COR_TRN_DEDUCTEE_DETAILS 
                                                WHERE  DEDUCTEE_NAME LIKE '" + cmnService.J_ReplaceQuote(txtEmployeeName.Text) + "%' " +
                                                       @"AND BATCH_HEADER_ID = " + lngBatchId + " " +
                                               @"GROUP  BY DEDUCTEE_NAME, 
                                                          DEDUCTEE_PAN, 
                                                          EMPLOYEE_SERIAL_NO
                                                UNION
                                                SELECT  EMPLOYEE_NAME AS NAME, 
                                                        EMPLOYEE_PAN  AS PAN, 
                                                        EMPLOYEE_SERIAL_NO AS EMPLOYEE_SERIAL_NO
                                                FROM   COR_TRN_SALARY_DETAILS 
                                                WHERE  EMPLOYEE_NAME LIKE '" + cmnService.J_ReplaceQuote(txtEmployeeName.Text) + "%' " +
                                                      @"AND BATCH_HEADER_ID = " + lngBatchId + " " +
                                               @"GROUP  BY EMPLOYEE_PAN, 
                                                          EMPLOYEE_NAME, 
                                                          EMPLOYEE_SERIAL_NO
                                                UNION
                                                SELECT EMPLOYEE_NAME  AS NAME,
                                                        EMPLOYEE_PAN  AS PAN, 
                                                        EMPLOYEE_REF  AS EMPLOYEE_SERIAL_NO
                                                FROM   MST_EMPLOYEE, MST_COMPANY
                                                WHERE  MST_EMPLOYEE.COMPANY_ID  = MST_COMPANY.COMPANY_ID
                                                AND    MST_COMPANY.TAN_NO       = '" + txtTAN.Text + @"'  
                                                AND    EMPLOYEE_NAME LIKE '" + TDSMAN.Classes.TDSMAN.T_DeducteeSearchLikeOperator + cmnService.J_ReplaceQuote(txtEmployeeName.Text) + "%' " +
                                              @"AND    MST_EMPLOYEE.INACTIVE_FLAG = 0) AS SD
                                                ORDER  BY SD.NAME"; 
                }
                else
                {
                    strSQLShowHelpDeductee = @"SELECT  TOP 10 SD.NAME,
                                                             SD.PAN
                                                FROM (
                                                SELECT DEDUCTEE_NAME AS NAME, 
                                                       DEDUCTEE_PAN         AS PAN
                                                FROM   COR_TRN_DEDUCTEE_DETAILS 
                                                WHERE  DEDUCTEE_NAME LIKE '" + cmnService.J_ReplaceQuote(txtEmployeeName.Text) + "%' " +
                                                       @"AND BATCH_HEADER_ID = " + lngBatchId + " " +
                                               @"GROUP  BY DEDUCTEE_NAME, 
                                                          DEDUCTEE_PAN
                                                UNION
                                                SELECT  EMPLOYEE_NAME AS NAME, 
                                                        EMPLOYEE_PAN  AS PAN
                                                FROM   COR_TRN_SALARY_DETAILS 
                                                WHERE  EMPLOYEE_NAME LIKE '" + cmnService.J_ReplaceQuote(txtEmployeeName.Text) + "%' " +
                                                      @"AND BATCH_HEADER_ID = " + lngBatchId + " " +
                                               @"GROUP  BY EMPLOYEE_PAN, 
                                                          EMPLOYEE_NAME
                                                UNION
                                                SELECT EMPLOYEE_NAME  AS NAME,
                                                        EMPLOYEE_PAN  AS PAN
                                                FROM   MST_EMPLOYEE, MST_COMPANY
                                                WHERE  MST_EMPLOYEE.COMPANY_ID  = MST_COMPANY.COMPANY_ID
                                                AND    MST_COMPANY.TAN_NO       = '" + txtTAN.Text + @"'  
                                                AND    EMPLOYEE_NAME LIKE '" + TDSMAN.Classes.TDSMAN.T_DeducteeSearchLikeOperator + cmnService.J_ReplaceQuote(txtEmployeeName.Text) + "%' " +
                                              @"AND    MST_EMPLOYEE.INACTIVE_FLAG = 0) AS SD
                                                ORDER  BY SD.NAME";
                }
                //
                drdShowDeducteeHelp = dmlService.J_ExecSqlReturnReader(strSQLShowHelpDeductee);
                //--
                if (drdShowDeducteeHelp == null)
                {
                    lstDeducteeHelp.Visible = false;
                    return;
                }
                else
                {
                    //if (TDSMAN.Classes.TDSMAN.T_ShareReferenceNoF24Q == true)
                    //    lstDeducteeHelp.Width = 525;
                    //else
                    //    lstDeducteeHelp.Width = 385;
                    //--
                    lstDeducteeHelp.Items.Clear();
                    //lstDeducteeHelp.Height = 19;
                    lstDeducteeHelp.Visible = true;
                    while (drdShowDeducteeHelp.Read())
                    {
                        //lstDeducteeHelp.Items.Add(new ListBoxItem(drdShowDeducteeHelp["EMPLOYEE_NAME"].ToString().PadRight(32) + drdShowDeducteeHelp["EMPLOYEE_PAN"].ToString().PadRight(13) + drdShowDeducteeHelp["EMPLOYEE_CATEGORY"]));
                        if (TDSMAN.Classes.TDSMAN.T_ShareReferenceNoF24Q == true) //-- 2020/06/03
                            lstDeducteeHelp.Items.Add(new ListBoxItem(drdShowDeducteeHelp["NAME"].ToString().PadRight(32) + drdShowDeducteeHelp["PAN"].ToString().PadRight(20) + drdShowDeducteeHelp["EMPLOYEE_SERIAL_NO"].ToString()));
                        else
                            lstDeducteeHelp.Items.Add(new ListBoxItem(drdShowDeducteeHelp["NAME"].ToString().PadRight(32) + drdShowDeducteeHelp["PAN"].ToString()));
                        //--
                        //if (lstDeducteeHelp.Height <= 300)
                        //    lstDeducteeHelp.Height = lstDeducteeHelp.Height + 19;
                    }
                    //--
                    if (lstDeducteeHelp.Items.Count <= 0)
                        lstDeducteeHelp.Visible = false;
                }
                //-----------------------------------------------------------
                drdShowDeducteeHelp.Close();
                drdShowDeducteeHelp.Dispose();
                //-----------------------------------------------------------
            }
            catch (Exception err_handler)
            {
                drdShowDeducteeHelp.Close();
                drdShowDeducteeHelp.Dispose();
                cmnService.J_UserMessage(err_handler.Message);
            }
        }

        #endregion

        #region lblTotalIncome_TextChanged
        private void lblTotalIncome_TextChanged(object sender, EventArgs e)
        {
            if (blnRestrictIncomeTaxCalculation == true) return;
            if ((cmbEmployeeCategory.SelectedIndex <= 0) || (Convert.ToDouble(lblTotalIncome.Text) <= 0))
            {
                lblTaxOnTotalIncomeCalculated.Text = "0.00";
                lblTaxCalculatedECess.Text = "0.00";
                lblCalculatedSurcharge.Text = "0.00";
                lblTaxDeductingRebateCalculated.Text = "0.00";
