                        ////-----------------------------------------------------------
                        //dmlService.J_setGridPosition(ref this.dgcViewSalaryDetails, dsetGridClone, lngTempSearchId);
                        //break;
                        #endregion
                        //==================================================================
                        //--
                        #region RESTORE
                        //##################################################################
                        //-- ADDED BY @@DHRUB--2015-08-20
                        //-- RESTORE PART
                        //------------------------------------------------------------------
                        if (BtnDelete.Text == T_DeleteRestoreText.Restore)
                        {
                            lblMode.Text = "Restore Mode";
                            //------------------------------------------------------------------
                            //-- RETRIEVE MODE FROM COR_TRN_SALARY_DETAILS
                            //------------------------------------------------------------------
                            strSQL = "SELECT MODE FROM COR_TRN_SALARY_DETAILS WHERE TRN_SALARY_DETAILS_ID = " + lngSearchId;
                            //-- 
                            //------------------------------------------------------------------
                            //------------------------------------------------------------------
                            #region [ MODE -> DELETED  ]
                            //-- WHILE MODE-- [ DELETED ] 
                            if (Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)) == T_CorrectionMode.Delete)
                            {
                                if (cmnService.J_UserMessage("Are you sure you want to restore this record?", MessageBoxButtons.YesNo) == DialogResult.Yes)
                                {
                                    //Restoring the deleted data
                                    strSQL = " UPDATE COR_TRN_SALARY_DETAILS " +
                                             " SET    MODE                  = '' " +
                                             " WHERE  TRN_SALARY_DETAILS_ID = " + lngSearchId + "";

                                    if (dmlService.J_ExecSql(strSQL) == false)
                                    {
                                        lblMode.Text = J_Mode.Add; chkPopulateCalculation.Checked = true;
                                        //txtDeducteeName.Select();
                                        return;
                                    }
                                }
                                else return;
                            }
                            #endregion
                            //------------------------------------------------------------------
                            #region [  Mode - > UPDATED  ]
                            //------------------------------------------------------------------
                            else
                            {
                                if (cmnService.J_UserMessage("Are you sure you want to restore this record to its original values?", MessageBoxButtons.YesNo) == DialogResult.Yes)
                                {
                                    // SETTING MODE OF THE RECORD AS PAN_UPDATE_INDICATOR IS ON AND INITIALISING MODIFIED VALUES
                                    strSQL = "UPDATE COR_TRN_SALARY_DETAILS " +
                                             "INNER JOIN COR_HDR_SALARY_DETAILS " +
                                             "       ON  COR_TRN_SALARY_DETAILS.HDR_SALARY_DETAILS_ID      = COR_HDR_SALARY_DETAILS.HDR_SALARY_DETAILS_ID  " +
                                             "SET    COR_TRN_SALARY_DETAILS.MODE                           = '', " +
                                             "       COR_TRN_SALARY_DETAILS.PAN_UPDATION_INDICATOR         =  " + T_UPDATION_INDICATOR.OFF + ",            " +
                                             "       COR_TRN_SALARY_DETAILS.EMPLOYEE_PAN                   = COR_HDR_SALARY_DETAILS.EMPLOYEE_PAN           " +
                                             " WHERE COR_TRN_SALARY_DETAILS.TRN_SALARY_DETAILS_ID          = " + lngSearchId + "";
                                    if (dmlService.J_ExecSql(strSQL) == false)
                                    {
                                        lblMode.Text = J_Mode.Add; chkPopulateCalculation.Checked = true;
                                        //txtDeducteeName.Select();
                                        return;
                                    }
                                }
                                else return;
                            }
                            #endregion
                            //------------------------------------------------------------------
                            //------------------------------------------------------------------
                            lngTempSearchId = lngSearchId;

                            strSQL = strQuery + "ORDER BY " + strOrderBy;
                            //-----------------------------------------------------------
                            if (dsetGridClone != null) dsetGridClone.Clear();
                            dsetGridClone = dmlService.J_ShowDataInGrid(ref dgcViewSalaryDetails, strSQL, strMatrix);       //Show Data into the Grid
                            if (dsetGridClone == null) return;
                            //-----------------------------------------------------------
                            lblMode.Text = J_Mode.Add;
                            cmnService.J_StatusButton(this, lblMode.Text); 
                            chkPopulateCalculation.Checked = true;
                            //
                            BtnEdit.Enabled = false;
                            BtnEdit.BackColor = Color.LightGray;
                            //--
                            BtnExit.Enabled = true;
                            BtnExit.BackColor = Color.Lavender;
                            //--
                            BtnDelete.Enabled = true;
                            BtnDelete.BackColor = Color.Lavender;
                            //--
                            BtnSearch.Enabled = true;
                            BtnSearch.BackColor = Color.Lavender;
                            //--
                            BtnRefresh.Enabled = true;
                            BtnRefresh.BackColor = Color.Lavender;
                            //--
                            LoadSalaryDetailsGrid(lngBatchId);
                            //--
                            dmlService.J_setGridPosition(ref this.dgcViewSalaryDetails, dsetGridClone, lngTempSearchId);
                            return;
                            //------------------------------------------------------------------
                        }
                        #endregion
                        //##################################################################
                        //--
                        #region DELETE
                        //-- 
                        //-- DELETE
                        else if (BtnDelete.Text == T_DeleteRestoreText.Delete)
                        {
                            //-----------------------------------------------------------
                            dmlService.J_BeginTransaction();
                            //-- ANIK - 2017-02-24 - FROM FVU 5.4
                            strSQL = @"SELECT MODE 
                                       FROM   COR_TRN_SALARY_DETAILS 
                                       WHERE  TRN_SALARY_DETAILS_ID = " + lngSearchId;
                            if (Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)) == T_CorrectionMode.Form26A_27BA &&
                                cmnService.J_ReturnInt64Value(txtFAYearID.Text.Trim()) >= T_FinancialYearID.F2007_08ID)
                            {
                                cmnService.J_UserMessage("Modification/Deletion not allowed as Form 26A/27BA has been generated by IT Dept.");
                                lblMode.Text = J_Mode.Add; chkPopulateCalculation.Checked = true;
                                dmlService.J_Rollback();
                                return;
                            }
                            //--
                            //-----------------------------------------------------------
                            //-- CHECK THE TRANSACTION
                            //-----------------------------------------------------------------------
                            //if (cmnService.J_UserMessage("Are you sure you mark '" + dgcViewSalaryDetails.CurrentRow.Cells["EMPLOYEE_NAME"].Value.ToString() +
                            //                              "' for deletion ?", MessageBoxButtons.YesNo, MessageBoxIcon.Question, MessageBoxDefaultButton.Button2) == DialogResult.No)
                            //{
                            //    lblMode.Text = J_Mode.Add;
                            //    dmlService.J_Rollback();
                            //    return;
                            //}
                            //
                            strSQL = "SELECT IMPORT_FLAG FROM COR_TRN_SALARY_DETAILS WHERE TRN_SALARY_DETAILS_ID = " + lngSearchId + "";

                            long lngSD_IMPORT_FLAG = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)));

                            if (lngSD_IMPORT_FLAG == 1)
                            {
                                if (cmnService.J_UserMessage("Are you sure to mark '" + dgcViewSalaryDetails.CurrentRow.Cells["EMPLOYEE_NAME"].Value.ToString() +
                                                          "' for deletion ?", MessageBoxButtons.YesNo, MessageBoxIcon.Question, MessageBoxDefaultButton.Button2) == DialogResult.No)
                                {
                                    lblMode.Text = J_Mode.Add; chkPopulateCalculation.Checked = true;
                                    dmlService.J_Rollback();
                                    return;
                                }
                                //Modified by Shrey Kejriwal on 30/12/2011
                                // SETTING MODE OF THE RECORD AS 'D' AND INITIALISING MODIFIED VALUES
                                strSQL = "UPDATE COR_TRN_SALARY_DETAILS " +
                                         "INNER JOIN COR_HDR_SALARY_DETAILS " +
                                         "       ON  COR_TRN_SALARY_DETAILS.HDR_SALARY_DETAILS_ID = " +
                                         "              COR_HDR_SALARY_DETAILS.HDR_SALARY_DETAILS_ID " +
                                         "SET    COR_TRN_SALARY_DETAILS.MODE                   = '" + T_CorrectionMode.Delete + "', " +
                                         "       COR_TRN_SALARY_DETAILS.EMPLOYEE_PAN           = COR_HDR_SALARY_DETAILS.EMPLOYEE_PAN, " +
                                         "       COR_TRN_SALARY_DETAILS.PAN_UPDATION_INDICATOR =  " + T_UPDATION_INDICATOR.OFF + " " +
                                         "WHERE  COR_TRN_SALARY_DETAILS.TRN_SALARY_DETAILS_ID = " + lngSearchId + "";
                                if (dmlService.J_ExecSql(strSQL) == false)
                                {
                                    lblMode.Text = J_Mode.Add; chkPopulateCalculation.Checked = true;
                                    //txtDeducteeName.Select();
                                    return;
                                }
                                //
                                //-- 2019/05/21
                                if (cmnService.J_ReturnInt64Value(txtFAYearID.Text.Trim()) >= T_FinancialYearID.F2018_19ID)
                                {
                                    strSQL = @"SELECT COUNT(*) FROM COR_TRN_SALARY_DETAILS 
                                           WHERE TRN_SALARY_DETAILS_ID  =  " + lngSearchId + @" 
                                           AND   MODE                  = '" + T_CorrectionMode.Delete + @"' 
                                           AND   IMPORT_FLAG           = 1 
                                           AND   TS_GS_SEC_17_1 + TS_GS_SEC_17_2 + TS_GS_SEC_17_3 = 0";
                                    if (cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL))) > 0)
                                    {
                                        strSQL = "UPDATE COR_TRN_SALARY_DETAILS SET " +
                                        "                TS_GS_SEC_17_1         =  TS_BALANCE ," +
                                        "                AIS_ITEM_1             =  AIS_Total , " +
                                        "                CVIA_SEC80C_DED_TOTAL  =  CVIA_SEC80CCE_TOTAL_DED_AMOUNT + CVIA_SEC80CCG_DED_AMOUNT  " +
                                        @"        WHERE  TRN_SALARY_DETAILS_ID  =  " + lngSearchId + @" 
                                              AND    MODE                  = '" + T_CorrectionMode.Delete + @"' 
                                              AND    IMPORT_FLAG           = 1 
                                              AND    TS_GS_SEC_17_1 + TS_GS_SEC_17_2 + TS_GS_SEC_17_3 = 0";
                                        if (dmlService.J_ExecSql(strSQL) == false)
                                        {
                                            lblMode.Text = J_Mode.Add; chkPopulateCalculation.Checked = true;
                                            return;
                                        }
                                    }
                                }
                            }
                            else
                            {
                                if (cmnService.J_UserMessage("Are you sure to delete '" + dgcViewSalaryDetails.CurrentRow.Cells["EMPLOYEE_NAME"].Value.ToString() +
                                                             "' ?", MessageBoxButtons.YesNo, MessageBoxIcon.Question, MessageBoxDefaultButton.Button2) == DialogResult.No)
                                {
                                    lblMode.Text = J_Mode.Add; chkPopulateCalculation.Checked = true;
                                    dmlService.J_Rollback();
                                    return;
                                }
                                // RECALCALUTING SRL NO.
                                //Added by Shrey Kejriwal on 10/01/2012
                                long lngSalarySerialNo = Convert.ToInt64(dmlService.J_ExecSqlReturnScalar("SELECT SL_NO FROM COR_TRN_SALARY_DETAILS WHERE  TRN_SALARY_DETAILS_ID = " + lngSearchId));
                                //
                                strSQL = "UPDATE COR_TRN_SALARY_DETAILS " +
                                         "SET    SL_NO = SL_NO - 1 " +
                                         "WHERE  SL_NO > " + lngSalarySerialNo + " " +
                                         "AND    BATCH_HEADER_ID = " + lngBatchId;
                                if (dmlService.J_ExecSql(strSQL) == false)
                                {
                                    lblMode.Text = J_Mode.Add;
                                    dmlService.J_Rollback();
                                    return;
                                }

                                //Commented by Shrey Kejriwal on 10/01/2012
                                //if (TdsMan.T_UpdateSrlNo(cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar("SELECT SL_NO FROM COR_TRN_SALARY_DETAILS WHERE  TRN_SALARY_DETAILS_ID = " + lngSearchId))),
                                //    lngBatchId, Updt_SrlNo.SalaryDetailSrlNo) == false) return;
                                //-----------------------------------------------------------
                                strSQL = "DELETE FROM COR_TRN_SALARY_DETAILS WHERE TRN_SALARY_DETAILS_ID =  " + lngSearchId + "";
                                //-----------------------------------------------------------
                                if (dmlService.J_ExecSql(strSQL) == false)
                                {
                                    lblMode.Text = J_Mode.Add; chkPopulateCalculation.Checked = true;
                                    dmlService.J_Rollback();
                                    return;
                                }
                            }
                            //-----------------------------------------------------------
                            dmlService.J_Commit();
                            cmnService.J_PanelMessage(0, J_Msg.DeleteMode);
                            //-----------------------------------------------------------
                            strSQL = strQuery + "ORDER BY " + strOrderBy;

                            lngTempSearchId = lngSearchId;

                            //-----------------------------------------------------------
                            if (dsetGridClone != null) dsetGridClone.Clear();
                            dsetGridClone = dmlService.J_ShowDataInGrid(ref dgcViewSalaryDetails, strSQL, strMatrix);       //Show Data into the Grid
                            if (dsetGridClone == null) return;
                            //-----------------------------------------------------------
                            lblMode.Text = J_Mode.Add;
                            cmnService.J_StatusButton(this, lblMode.Text); 
                            chkPopulateCalculation.Checked = true;
                            //
                            BtnEdit.Enabled = false;
                            BtnEdit.BackColor = Color.LightGray;
                            //--
                            BtnExit.Enabled = true;
                            BtnExit.BackColor = Color.Lavender;
                            //--
                            BtnDelete.Enabled = true;
                            BtnDelete.BackColor = Color.Lavender;
                            //--
                            BtnSearch.Enabled = true;
                            BtnSearch.BackColor = Color.Lavender;
                            //--
                            BtnRefresh.Enabled = true;
                            BtnRefresh.BackColor = Color.Lavender;
                            //--
                            LoadSalaryDetailsGrid(lngBatchId);
                            //--
                            txtSalaryDetailSrlNo.Text = Convert.ToString(dmlService.J_ReturnMaxValue("COR_TRN_SALARY_DETAILS", "SL_NO", "BATCH_HEADER_ID = " + lngBatchId + "") + 1);
                            //-----------------------------------------------------------
                            dmlService.J_setGridPosition(ref this.dgcViewSalaryDetails, dsetGridClone, lngTempSearchId);
                        }
                        #endregion
                        //--

                        break;
                        #endregion
                }
            }
            catch (Exception err_handler)
            {
                dmlService.J_Rollback();
                cmnService.J_UserMessage(err_handler.Message);
            }
        }
        #endregion

