        #region ShowRecord
        private bool ShowRecord(long Id)
        {
            //----------------------------------------------------------
            //ADDED BY DHRUB ON 30/01/2014  FOR Tax Calculation Summary 
            //----------------------------------------------------------
            blnRestrictIncomeTaxCalculation = true;

            IDataReader drdShowRecord = null;
            //-----------------------------------------------------------
            /* (1) Column Value
             * (2) Column Data Type
             * (3) Replace String
             * (4) Replace String Data Type */
            //-----------------------------------------------------------
            //-----------------------------------------------------------
            try
            {
                string[,] strShowHelpEmployeeMatrix = {{"COR_TRN_SALARY_DETAILS.EMPLOYEE_CATEGORY = 'G'", "F", T_EmployeeCategory.General, "T"},
                                                       {"COR_TRN_SALARY_DETAILS.EMPLOYEE_CATEGORY = 'W'", "F", T_EmployeeCategory.Woman, "T"},
                                                       {"COR_TRN_SALARY_DETAILS.EMPLOYEE_CATEGORY = 'S'", "F", T_EmployeeCategory.SeniorCitizen, "T"},
                                                       {"COR_TRN_SALARY_DETAILS.EMPLOYEE_CATEGORY = 'O'", "F", T_EmployeeCategory.SuperSeniorCitizen, "T"}};
                //
                strSQL = "SELECT  COR_TRN_SALARY_DETAILS.TRN_SALARY_DETAILS_ID           AS TRN_SALARY_DETAILS_ID," +
                    "             COR_TRN_SALARY_DETAILS.BATCH_HEADER_ID                 AS BATCH_HEADER_ID," +
                    "             COR_TRN_SALARY_DETAILS.EMPLOYEE_NAME                   AS EMPLOYEE_NAME," +
                    "             COR_TRN_SALARY_DETAILS.EMPLOYEE_PAN                    AS EMPLOYEE_PAN," +
                    "            " + cmnService.J_SQLDBFormat(strShowHelpEmployeeMatrix, J_SQLColFormat.Case_End) + " AS EMPLOYEE_CATEGORY," +
                    "            " + cmnService.J_SQLDBFormat("COR_TRN_SALARY_DETAILS.FROM_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + " AS FROM_DATE," +
                    "            " + cmnService.J_SQLDBFormat("COR_TRN_SALARY_DETAILS.TO_DATE", J_SQLColFormat.DateFormatDDMMYYYY) + " AS TO_DATE," +
                    "             COR_TRN_SALARY_DETAILS.MODE                            AS MODE," +
                    "             COR_TRN_SALARY_DETAILS.TS_BALANCE                      AS TS_BALANCE," +
                    "             COR_TRN_SALARY_DETAILS.US_16_EA                        AS US_16_EA," +
                    "             COR_TRN_SALARY_DETAILS.US_16_TE                        AS US_16_TE," +
                    "             COR_TRN_SALARY_DETAILS.US_16_IA                        AS US_16_IA," + //-- 2019/04/04
                    "             COR_TRN_SALARY_DETAILS.US_16_AGGREGATE                 AS US_16_AGGREGATE," +
                    "             COR_TRN_SALARY_DETAILS.INCOME_CHARGEABLE               AS INCOME_CHARGEABLE," +
