                    "             COR_HDR_SALARY_DETAILS.CVIA_SEC80CCH_DED_AMOUNT        AS CVIA_SEC80CCH_DED_AMOUNT," +
                    "             COR_HDR_SALARY_DETAILS.CVIA_SEC80CCH_1_GROSS_AMOUNT    AS CVIA_SEC80CCH_1_GROSS_AMOUNT," +
                    "             COR_HDR_SALARY_DETAILS.CVIA_SEC80CCH_1_DED_AMOUNT      AS CVIA_SEC80CCH_1_DED_AMOUNT," +
                    "             COR_HDR_SALARY_DETAILS.SEC10_14_AMOUNT                 AS SEC10_14_AMOUNT," +
                    "             COR_HDR_SALARY_DETAILS.TDS_US_192_2B_AMOUNT            AS TDS_US_192_2B_AMOUNT  " +
                    "     FROM    (COR_HDR_SALARY_DETAILS LEFT JOIN COR_TRN_SALARY_DETAILS " +
                    "             ON COR_HDR_SALARY_DETAILS.HDR_SALARY_DETAILS_ID = COR_TRN_SALARY_DETAILS.HDR_SALARY_DETAILS_ID) " +
                    "     WHERE   COR_TRN_SALARY_DETAILS.TRN_SALARY_DETAILS_ID = " + Id + " ";

