        #region CheckExcelStructure
        private bool CheckExcelStructure(string ExcelFilePath)
        {
            try
            {
                if (rbnAddDeductees.Checked == true)
                {
                    #region ADD DEDUCTEE_DETAILS
                    //--
                    if (TdsMan.T_IsExcelDatabaseObjectExist("Salary Details", null, con) == false)
                    {
                        con.Close();
                        con.Dispose();
                        return false;
                    }
                    //
                    if ((TdsMan.T_IsExcelDatabaseObjectExist("Salary Details", "Employee Serial No (327)", con) == false)
                        &&
                        (TdsMan.T_IsExcelDatabaseObjectExist("Salary Details", "Employee Serial No (328)", con) == false))
                    {
                        con.Close();
                        con.Dispose();
                        return false;
                    }
                    //
                    if ((TdsMan.T_IsExcelDatabaseObjectExist("Salary Details", "PAN of the Employee (328)", con) == false)
                        &&
                        (TdsMan.T_IsExcelDatabaseObjectExist("Salary Details", "PAN of the Employee (329)", con) == false))
                    {
                        con.Close();
                        con.Dispose();
                        return false;
                    }
                    //
                    if ((TdsMan.T_IsExcelDatabaseObjectExist("Salary Details", "Name of the Employee (329)", con) == false)
                        &&
                        (TdsMan.T_IsExcelDatabaseObjectExist("Salary Details", "Name of the Employee (330)", con) == false))
                    {
                        con.Close();
                        con.Dispose();
                        return false;
                    }
