        #region VALIDATE_DATA_CSV
        private bool VALIDATE_DATA_CSV()
        {
            string strSheetName = "";
            string strMidSubString = "";
            string strUpper = "";
            try
            {
                //if (CREATE_TEMP_ERR_TABLES() == false)
                //    return false;
                //--
                if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                {
                    strMidSubString = "SUBSTRING";
                    strUpper = "UPPER";
                }
                else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                {
                    strMidSubString = "MID";
                    strUpper = "UCASE";
                }
                //--
                if (rbnAddDeductees.Checked == true)
                {
                    //-- TAX_115BAC
                    #region TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS (TAX_115BAC)
                    if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS, "TAX_115BAC") == false)
                    {
                        strSQL = dmlService.ReturnALTERSyntaxSequelServer(TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS, "TAX_115BAC", "NUMBER", "", "", "0");
                        dmlService.J_ExecSql(strSQL);
                        //
                        strSQL = "UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + " SET TAX_115BAC = 0";
                        dmlService.J_ExecSql(strSQL);
                    }
                    #endregion
                    //--

                    #region SALARY DETAILS

                    strSheetName = T_Sheet_Name.SALARY_DETAILS;

                    #region EMPLOYEE PAN

                    //UPDATE ALL NULL RECORDS TO ''
                    strSQL = "UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + " SET EMPLOYEE_PAN = '' WHERE EMPLOYEE_PAN IS NULL";
                    dmlService.J_ExecSql(strSQL);


                    //BLANK OR 0 CHECK
                    strSQL = "SELECT COUNT(*)" +
                        "     FROM   " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + " " +
                        "     WHERE  EMPLOYEE_PAN = ''" +
                        "     AND    EMPLOYEE_PAN NOT IN (SELECT ERR_ROW FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ERR_VALIDATION + " " +
                        "                                 WHERE ERR_SHEET = '" + strSheetName + "')";
                    //
                    lngRowCount = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)));

                    if (lngRowCount > 0)
                    {
                        // Modified by Ripan Paul on 20-06-2013
                        strSQL = " INSERT INTO " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ERR_VALIDATION + "(ERR_TYPE, ERR_ROW, ERR_COLUMN, ERR_SHEET)" +
                            "      SELECT '" + T_Error_Type.BLANK_NULL_CHECK + "'," +
                            "             " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".RUNNING_SERIAL_NO_ORDER AS ERR_ROW," +
                            "             'EMPLOYEE_PAN'," +
                            "             '" + strSheetName + "'" +
                            "     FROM   " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + " LEFT JOIN " +
                            "           (SELECT ERR_ROW " +
                            "            FROM   " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ERR_VALIDATION + " " +
                            "            WHERE  ERR_SHEET = '" + strSheetName + "') AS ERR_V " +
                            "     ON     " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".RUNNING_SERIAL_NO_ORDER = ERR_V.ERR_ROW " +
                            "     WHERE  ERR_V.ERR_ROW                       IS NULL " +
                            "     AND    " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN      = '' ";


                        //
                        if (dmlService.J_ExecSql(strSQL) == false)
                            return false;
                    }

                    //LENGTH CHECK
                    strSQL = "SELECT COUNT(*)" +
                        "     FROM   " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + " " +
                        "     WHERE  LEN(EMPLOYEE_PAN) <> 10" +
                        "     AND    EMPLOYEE_PAN NOT IN (SELECT ERR_ROW FROM " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ERR_VALIDATION + " " +
                        "                                      WHERE ERR_SHEET = '" + strSheetName + "')";
                    //
                    lngRowCount = cmnService.J_ReturnInt32Value(Convert.ToString(dmlService.J_ExecSqlReturnScalar(strSQL)));

                    if (lngRowCount > 0)
                    {
                        strSQL = " INSERT INTO " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ERR_VALIDATION + "(ERR_TYPE, ERR_ROW, ERR_COLUMN, ERR_SHEET)" +
                            "      SELECT '" + T_Error_Type.LENGTH_CHECK + "'," +
                            "             " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".RUNNING_SERIAL_NO_ORDER AS ERR_ROW," +
