                            "     WHERE  ERR_V.ERR_ROW                        IS NULL " +
                            "     AND    LEN(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN) <> 10 ";

