                        strSQL = "SELECT COUNT(*)" +
                                "     FROM   " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + " " +
                                "     WHERE  (ISNUMERIC(LEFT(EMPLOYEE_PAN,1)) <> 0" +
                                "     OR     ISNUMERIC(SUBSTRING(EMPLOYEE_PAN,2,1)) <> 0 " +
