                                "     ON     " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".RUNNING_SERIAL_NO_ORDER = ERR_V.ERR_ROW " +
                                "     WHERE  ERR_V.ERR_ROW                                         IS NULL " +
                                "     AND   (ISNUMERIC(LEFT(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN, 1))   <> 0 " +
                                "     OR     ISNUMERIC(SUBSTRING(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN, 2, 1)) <> 0 " +
                                "     OR     ISNUMERIC(SUBSTRING(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN, 3, 1)) <> 0 " +
                                "     OR     ISNUMERIC(SUBSTRING(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN, 4, 1)) <> 0 " +
                                "     OR     ISNUMERIC(SUBSTRING(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN, 5, 1)) <> 0 " +
                                "     OR     ISNUMERIC(SUBSTRING(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN, 6, 4))  = 0 " +
                                "     OR     ISNUMERIC(RIGHT(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN, 1))  = -1) " +
                                "     AND    " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN <> 'PANNOTAVBL' ";
                        else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                            strSQL = " INSERT INTO " + TDSMAN.Classes.TDSMAN.T_tblTEMP_ERR_VALIDATION + "(ERR_TYPE, ERR_ROW, ERR_COLUMN, ERR_SHEET)" +
