                                "     WHERE  ERR_V.ERR_ROW                                         IS NULL " +
                                "     AND   (ISNUMERIC(LEFT(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN, 1))   <> 0 " +
                                "     OR     ISNUMERIC(MID(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN, 2, 1)) <> 0 " +
                                "     OR     ISNUMERIC(MID(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN, 3, 1)) <> 0 " +
                                "     OR     ISNUMERIC(MID(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN, 4, 1)) <> 0 " +
                                "     OR     ISNUMERIC(MID(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN, 5, 1)) <> 0 " +
                                "     OR     ISNUMERIC(MID(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN, 6, 4))  = 0 " +
                                "     OR     ISNUMERIC(RIGHT(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".EMPLOYEE_PAN, 1))  = -1) " +
