        #region INSERT_SALARY_DATA
        public bool INSERT_SALARY_DATA(long BasicInfoID)
        {
            try
            {
                //--
                string strUpper = "";
                if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                {
                    strUpper = "UPPER";
                }
                else if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                {
                    strUpper = "UCASE";
                }
                //--
                #region TDS INCLUDING SUPERANNUATION
                #region T_tblTEMP_SALARY_DETAILS (CONTRIBUTIONS_SUPERANN_YN)
                if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS, "CONTRIBUTIONS_SUPERANN_YN") == false)
                {
                    //strSQL = "ALTER TABLE TRN_SALARY_DETAILS ADD COLUMN LANDLORD_PAN_COUNT TEXT(2) NOT NULL DEFAULT \"\"";
                    strSQL = dmlService.ReturnALTERSyntaxSequelServer(TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS, "CONTRIBUTIONS_SUPERANN_YN", "TEXT", "5", "NOT NULL", "\"\"");
                    dmlService.J_ExecSql(strSQL);
                    strSQL = "UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + " SET CONTRIBUTIONS_SUPERANN_YN = ''";
                    dmlService.J_ExecSql(strSQL);
                }
                #endregion

                #region T_tblTEMP_SALARY_DETAILS (GROSS_TOTAL_INC)
                if (dmlService.J_IsDatabaseObjectExist(TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS, "GROSS_TOTAL_INC") == false)
                {
                    //strSQL = "ALTER TABLE TRN_SALARY_DETAILS ADD COLUMN LANDLORD_PAN_COUNT TEXT(2) NOT NULL DEFAULT \"\"";
                    strSQL = dmlService.ReturnALTERSyntaxSequelServer(TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS, "GROSS_TOTAL_INC", "NUMBER", "", "NOT NULL", "0");
                    dmlService.J_ExecSql(strSQL);
                    strSQL = "UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + " SET GROSS_TOTAL_INC = 0";
                    dmlService.J_ExecSql(strSQL);
                    //
                    strSQL = dmlService.ReturnALTERSyntaxSequelServer(TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS, "AMT_REPAID", "NUMBER", "", "NOT NULL", "0");
                    dmlService.J_ExecSql(strSQL);
                    strSQL = "UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + " SET AMT_REPAID = 0";
                    dmlService.J_ExecSql(strSQL);
                    //
                    strSQL = dmlService.ReturnALTERSyntaxSequelServer(TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS, "AMT_TAX", "NUMBER", "", "NOT NULL", "0");
                    dmlService.J_ExecSql(strSQL);
                    strSQL = "UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + " SET AMT_TAX = 0";
                    dmlService.J_ExecSql(strSQL);
                }
                #endregion


                strSQL = @" UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS +
                         @" SET    GROSS_TOTAL_INC = " + cmnService.J_SQLDBFormat(TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".AMT_REPAID", J_SQLColFormat.ConvertToMoney) + " + " +
                                                cmnService.J_SQLDBFormat(TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".GROSS_TOTAL_INCOME", J_SQLColFormat.ConvertToMoney) + " " +
                          " WHERE  " + strUpper + "(LEFT(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".CONTRIBUTIONS_SUPERANN_YN, 1)) = 'Y'";
                dmlService.J_ExecSql(strSQL);

                #endregion
                //
                #region SHORTFALL EXCESS / DEDUCTION OF TAX
                //UPDATE TO 0 IF 'NULL'                
                strSQL = "UPDATE " + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + "  SET AMT_TAX = 0 WHERE AMT_TAX IS NULL";
                if (dmlService.J_ExecSql(strSQL) == false)
                {
                    return false;
                }
