                    "            '" + T_CorrectionMode.Add + "'," +
                    "             LEFT(" + TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS + ".CONTRIBUTIONS_SUPERANN_YN,1) AS SUPERANN_YN," +
