                    strSQL = dmlService.ReturnALTERSyntaxSequelServer(TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS, "SEC10_TOTAL_AMOUNT", "MONEY", "", "", "0");
                    dmlService.J_ExecSql(strSQL);
