                            WHERE  COR_TRN_SALARY_DETAILS.BATCH_HEADER_ID = " + lngBatchId;

                    if (dmlService.J_ExecSql(strSQL) == false)
                    {
                        return false;
                    }
                    #endregion
                }
                //-- ENTER REGULAR DEDUCTEE/EMPLOYEE MASTER
                TdsMan.CreateRegularDeducteeMasterFromCorrection(T_FormNo.F24Q.ToString(), txtQuarter.Text.Trim(), lngBatchId);
                //
                return true;
            }
            catch (Exception e)
            {
                return false;
            }
        }

