                    wsnew.get_Range("A1", "D1").Locked = true;
                }

                //
                wb.Save();
                wb.Close(m, m, m);

                wb = null;
                wbs = null;

                excelapp.Quit();
                excelapp = null;
                //--
                return true;
            }
            catch
            {
                this.Cursor = Cursors.Default;
                //
                cmnService.J_UserMessage("Export data to Excel failed");
                //
                return false;
            }
