        #region tlStrpXls_Click
        private void tlStrpXls_Click(object sender, EventArgs e)
        {
            try
            {
                if (J_Var.J_pDatabaseType != J_DatabaseType.SqlServer)
                {

                    string ExcelFilePath = "";
                    int intIncrement = 0;
                    long lngTotalEmployeeNo = 0;
                    string ExcelFileName = "EXPORTED_SD_DATA_BULK_DELETION";
                    //--
                    strSQL1 = @" SELECT COUNT(*) FROM COR_TRN_SALARY_DETAILS WHERE BATCH_HEADER_ID = " + lngBatchId + " " +
                              "    AND MODE NOT IN ('A', 'D', 'U') " +
                              "    and PAN_UPDATION_INDICATOR = 0 ";   //-- Added By Abhishek Dey On 15/11/2018 --
                    lngTotalEmployeeNo = Convert.ToInt64(dmlService.J_ExecSqlReturnScalar(strSQL1).ToString());

                    if (lngTotalEmployeeNo > 0)  //-- 17/11/2018 --
                    {
                        if (cmnService.J_UserMessage("Summary : \n No. of Employee(s): " + lngTotalEmployeeNo + " \nProceed ??", MessageBoxButtons.YesNo) == DialogResult.No)
                            return;
                    }
                    else
                    {
                        cmnService.J_UserMessage("No Employee available.", MessageBoxButtons.OK);
                        return;
                    }
                    //
                    this.Cursor = Cursors.WaitCursor;
                    // Create a new instance of FolderBrowserDialog.
                    FolderBrowserDialog folderBrowserDlg = new FolderBrowserDialog();
                    // A new folder button will display in FolderBrowserDialog.
                    folderBrowserDlg.ShowNewFolderButton = true;
                    //Show FolderBrowserDialog
                    DialogResult dlgResult = folderBrowserDlg.ShowDialog();
                    if (dlgResult.Equals(DialogResult.OK))
                    {
                        //Show selected folder path in textbox1.
                        ExcelFilePath = folderBrowserDlg.SelectedPath;
                        //Browsing start from root folder.
                        Environment.SpecialFolder rootFolder = folderBrowserDlg.RootFolder;
                    }
                    else
                        return;
                    //--
                    //--
                    string strNewExcelFileName = string.Empty; //-- 09/11/2018 --
                    strNewExcelFileName = ExcelFileName;
                    //--
                    do
                    {
                        if (cmnService.J_IsFileExist(Path.Combine(ExcelFilePath, ExcelFileName + ".xls")) == true )
                        {
                            intIncrement++;
                            ExcelFileName = strNewExcelFileName + " (" + intIncrement + ") ";
                        }
                    } while (cmnService.J_IsFileExist(Path.Combine(ExcelFilePath, ExcelFileName + ".xls")) == true);
                    //----
                    if (intIncrement > 0)
                        ExcelFileName = strNewExcelFileName + " (" + intIncrement + ") ";  //-- 09/11/2018 --
                    else
                        ExcelFileName = strNewExcelFileName;
                    //
                    ExcelFilePath = Path.Combine(ExcelFilePath, ExcelFileName + ".xls");
                    //
                    Excel.Application xlApp;
                    Excel.Workbook xlWorkBook;
                    //Excel.Worksheet xlWorkSheet;
                    object misValue = System.Reflection.Missing.Value;

                    //xlApp = new Excel.ApplicationClass();
                    xlApp = new Excel.Application();
                    xlWorkBook = xlApp.Workbooks.Add(misValue);

                    xlWorkBook.SaveAs(ExcelFilePath, Excel.XlFileFormat.xlOpenXMLWorkbook, misValue, misValue, misValue, misValue, Excel.XlSaveAsAccessMode.xlExclusive, misValue, misValue, misValue, misValue, misValue);

                    //------------------------------------
                    xlWorkBook.Close(true, misValue, misValue);
                    xlApp.Quit();

                    ReleaseObject(xlWorkBook);
                    ReleaseObject(xlApp);
                    //
                    #region BULK_DELETION_SD

                    #region Variable Declaration
                    // SALARY DETAILS
                    string strSDSerialNo = string.Empty;
                    string strEmployeePan = string.Empty;
                    string strEmployeeName = string.Empty;
                    string strTotalTaxDeductedAmount = string.Empty;

                    #endregion

                    #region Initialize Variable
                    // SALARY DETAILS
                    strSDSerialNo = "[Serial No]";
                    strEmployeePan = "[Employee Pan]";
                    strEmployeeName = "[Employee Name]";
                    strTotalTaxDeductedAmount = "[Total Tax Deducted]";


                    #endregion

                    if (CREATE_NEW_WORKSHEET(ExcelFilePath, T_Sheet_Name.DATA_FOR_BULK_DELETION_SD) == false) return;
                    if (WRITE_COLUMN_HEADER_BULK_DELETION_WORKSHEET(ExcelFilePath, T_Sheet_Name.DATA_FOR_BULK_DELETION_SD) == false) return;
                    //

                    strSQL1 = @" SELECT SL_NO AS " + strSDSerialNo + "," +
                                "        EMPLOYEE_PAN AS " + strEmployeePan + "," +
                                "        EMPLOYEE_NAME AS " + strEmployeeName + "," +
                                "        TOTAL_TAX_DEDUCTED_AMOUNT AS " + strTotalTaxDeductedAmount + " " +
                                "  FROM  COR_TRN_SALARY_DETAILS " +
                                "  WHERE BATCH_HEADER_ID = " + lngBatchId + " " +
                                "  AND   MODE NOT IN ('A', 'D', 'U') " +   //-- Added By Abhishek Dey On 13/11/2018 --
                                "  AND   IMPORT_FLAG     = 1 " +
                                "  AND   PAN_UPDATION_INDICATOR = 0 ";   //-- Added By Abhishek Dey On 15/11/2018 --

                    if (cmnService.J_ReturnInt64Value(txtFAYearID.Text.Trim()) >= T_FinancialYearID.F2007_08ID)
                    {
                        strSQL1 = strSQL1 + @" AND MODE <> '" + T_CorrectionMode.Form26A_27BA + "' ";
                    }

                    strSQL1 = strSQL1 + @" ORDER BY SL_NO ";

                    GC.WaitForPendingFinalizers();

                    if (ExportToExcelFromDataTable(strSQL1, T_Sheet_Name.DATA_FOR_BULK_DELETION_SD, ExcelFilePath) == false)
                    {
                        this.Cursor = Cursors.Default;
                        cmnService.J_UserMessage("Failed export data to excel ..", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }
                    //
                    if (DELETE_WORKSHEET(ExcelFilePath, "Sheet1") == false) //return;
                        if (DELETE_WORKSHEET(ExcelFilePath, "Sheet2") == false) //return;
                            if (DELETE_WORKSHEET(ExcelFilePath, "Sheet3") == false) //return;

                                if (KILL_EXCEL() == false)
                                    return;

                    #endregion
                    //
                    this.Cursor = Cursors.Default;
                    //
                    //Deleting Temporary files
                    Delete_TMP_Files(ExcelFilePath);
                    //
                    this.Cursor = Cursors.Default;

                    //OPEN THE EXCEL FILE
                    System.Diagnostics.Process.Start(ExcelFilePath);
                    //--
                }
            }
            catch (Exception ERR)
            {
                this.Cursor = Cursors.Default;
                cmnService.J_UserMessage(ERR.Message);
            }
        }
        #endregion


