                        File.Delete(strTemporaryfileSalaryPath);
                    //
                    if (blnSALARY_DETAILS_CHVIA == true)
                    {
                        //-- 2020/05/14
                        strTemporaryfileSalaryCHVIAPath = Path.Combine(strStartupPath, TDSMAN.Classes.TDSMAN.T_pProductSerial + "_SalaryDetailsCHVIA.txt");
                        if (File.Exists(strTemporaryfileSalaryCHVIAPath) == true)
                            File.Delete(strTemporaryfileSalaryCHVIAPath);
                        //
                    }
                }
                else
                {
                    strTemporaryfileSalaryPath = Path.Combine(strStartupPath, "SalaryDetails.txt");
                    //-- 2020/05/14                        
                    if (blnSALARY_DETAILS_CHVIA == true)
                    {
                        strTemporaryfileSalaryCHVIAPath = Path.Combine(strStartupPath, "SalaryDetailsCHVIA.txt");
                    }
                }
                string tableName = "";
                string textfileName = "";
                string strDDCsvPath = "";
                #endregion

                if (KILL_EXCEL() == false)
                    return false;
                //
                #region CSV VALIDATION
                string strImportTextName = "";
                //
                #region SALARY DETAILS
                if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
                {
                    if (rbnAddDeductees.Checked == true)
                        strImportTextName = TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS;
                    else if (rbnModifyDeductees.Checked == true)
                    {
                        if (rbnPANModificationSD.Checked == true)
                            strImportTextName = TDSMAN.Classes.TDSMAN.T_tblTEMP_SD_MODIFY_PAN;
                        else if (rbnBulkDeletion.Checked == true)
                            strImportTextName = TDSMAN.Classes.TDSMAN.T_tblTEMP_SD_DELETE;

                    }
                    //COPY .TDS FILE AS .TXT FILE TO IMPORT DATA TO ACCESS
                    if (File.Exists(Application.StartupPath + "\\" + strImportTextName + ".txt") == true)
                        File.Delete(Application.StartupPath + "\\" + strImportTextName + ".txt");
                    //
                    File.Copy(txtExcelPath.Text.Trim(), Application.StartupPath + "\\" + strImportTextName + ".txt", true);
                    //
                    //-- Creation of dump table from .CSV file
                    if (rbnAddDeductees.Checked == true)
                    {
                        if (T_BulkImportFromSDCSVFile(strImportTextName, false) == false) return false;
                        //
                        strSQL = @"DELETE FROM " + strImportTextName + " WHERE RUNNING_SERIAL_NO_ORDER = 'Serial No'";
                        dmlService.J_ExecSql(strSQL);
                        //-- DELETE BLANK ROW
                        strSQL = @"DELETE FROM " + strImportTextName + " WHERE RUNNING_SERIAL_NO_ORDER IS NULL";
                        dmlService.J_ExecSql(strSQL);
                        //--
                    }
                    else if (rbnModifyDeductees.Checked == true)
                    {
                        if (rbnPANModificationSD.Checked == true)
                        {
                            if (T_BulkImportPANModification(strImportTextName, false) == false) return false;
                            //
                            strSQL = @"DELETE FROM " + strImportTextName + " WHERE SR_NO = 'Sr No'";
                            dmlService.J_ExecSql(strSQL);
                            //-- DELETE BLANK ROW
                            strSQL = @"DELETE FROM " + strImportTextName + " WHERE SR_NO IS NULL";
                            dmlService.J_ExecSql(strSQL);
                            //--
                        }
                        else if (rbnBulkDeletion.Checked == true)
                        {
                            if (T_BulkImportBulkDeletion(strImportTextName, false) == false) return false;
                            //
                            strSQL = @"DELETE FROM " + strImportTextName + " WHERE SD_SERIAL_NO = 'Serial No'";
                            dmlService.J_ExecSql(strSQL);
                            //-- DELETE BLANK ROW
                            strSQL = @"DELETE FROM " + strImportTextName + " WHERE SD_SERIAL_NO IS NULL";
                            dmlService.J_ExecSql(strSQL);
                            //--
                        }
                    }                    
                }
                else if (J_Var.J_pDatabaseType == J_DatabaseType.SqlServer)
                {
                    //strImportTextName = TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS;
                    if (rbnAddDeductees.Checked == true)
                        strImportTextName = TDSMAN.Classes.TDSMAN.T_tblTEMP_SALARY_DETAILS;
                    else if (rbnModifyDeductees.Checked == true)
                    {
                        if (rbnPANModificationSD.Checked == true)
                            strImportTextName = TDSMAN.Classes.TDSMAN.T_tblTEMP_SD_MODIFY_PAN;
                        else if (rbnBulkDeletion.Checked == true)
                            strImportTextName = TDSMAN.Classes.TDSMAN.T_tblTEMP_SD_DELETE;
                    }
                    //
                    if (File.Exists(strStartupPath + "\\" + strImportTextName + ".txt") == true)
                        File.Delete(strStartupPath + "\\" + strImportTextName + ".txt");
                    //
                    File.Copy(txtExcelPath.Text.Trim(), strStartupPath + "\\" + strImportTextName + ".txt", true);
                    //
                    //Check 'n Create Temp Tables
                    if (dmlService.J_IsDatabaseObjectExist(strImportTextName) == true)
                    {
                        strSQL = "DELETE FROM [" + strImportTextName + "]";
                        dmlService.J_ExecSql(strSQL);
                    }
                    //--
                    if (Convert.ToString(File.ReadAllLines(strStartupPath + "\\" + strImportTextName + ".txt")) != "")
                    {
                        //--
                        strSQL = @"BULK INSERT [" + strImportTextName + "] FROM '" + strStartupPath + "\\" + strImportTextName + ".txt" + "' WITH (fieldterminator = ',', rowterminator = '\\n')";
                        dmlService.J_ExecSql(strSQL);
                        //
                        if (rbnAddDeductees.Checked == true)
                        {
                            strSQL = @"DELETE FROM " + strImportTextName + " WHERE RUNNING_SERIAL_NO_ORDER = 'Serial No'";
                            dmlService.J_ExecSql(strSQL);
                            //-- DELETE BLANK ROW
                            strSQL = @"DELETE FROM " + strImportTextName + " WHERE RUNNING_SERIAL_NO_ORDER IS NULL";
                            dmlService.J_ExecSql(strSQL);
                        }
                        else if (rbnModifyDeductees.Checked == true)
                        {
                            if (rbnPANModificationSD.Checked == true)
                            {
                                //
                                strSQL = @"DELETE FROM " + strImportTextName + " WHERE SR_NO = 'Sr No'";
                                dmlService.J_ExecSql(strSQL);
                                //-- DELETE BLANK ROW
                                strSQL = @"DELETE FROM " + strImportTextName + " WHERE SR_NO IS NULL";
                                dmlService.J_ExecSql(strSQL);
                                //--
                            }
                            else if (rbnBulkDeletion.Checked == true)
                            {
                                //if (T_BulkImportBulkDeletion(strImportTextName, false) == false) return false;
                            }
                        }
                    }
                }
                #endregion
                //                
                #endregion

                intLN = 0;
                return true;
                //############################################
            }
            catch (Exception e)
            {
                //strErrorMessage = "Invalid data format in Excel file, please check. " + intLN;
                //-- 2015/10/14
                cmnService.J_UserMessage(e.Message);
                con.Close();
                con.Dispose();
                return false;
            }
        }
        #endregion

        #region T_BulkImportFromSDCSVFile
        private bool T_BulkImportFromSDCSVFile(string ImportTableName, bool FirstRowAsColumnHeader)
        {
            //Recreating schema file
            if (File.Exists(Application.StartupPath + "\\schema.ini") == true)
                File.Delete(Application.StartupPath + "\\schema.ini");

            StreamWriter StreamWriter = new StreamWriter(Application.StartupPath + "\\schema.ini");
            StreamWriter.WriteLine("[" + ImportTableName + ".txt]");
            StreamWriter.WriteLine("ColNameHeader=" + (FirstRowAsColumnHeader == true ? "True" : "False") + "");
            StreamWriter.WriteLine("Format=Delimited(,)");
            StreamWriter.WriteLine("MaxScanRows=0");
            StreamWriter.WriteLine("HDR = Yes");
            StreamWriter.WriteLine("CharacterSet=ANSI");
            //
            #region COLUMN NAMES

            StreamWriter.WriteLine(@"Col1=RUNNING_SERIAL_NO_ORDER Char 
                                        Col2=EMPLOYEE_PAN Char 
                                        Col3=EMPLOYEE_NAME Char 
                                        Col4=CATEGORY Char 
                                        Col5=FROM_DATE Char 
                                        Col6=TO_DATE Char 
                                        Col7=TAX_115BAC Char 
                                        Col8=TS_GS_SEC_17_1 Char 
                                        Col9=TS_GS_SEC_17_2 Char 
                                        Col10=TS_GS_SEC_17_3 Char 
                                        Col11=TS_BALANCE Char 
                                        Col12=SEC10_5_AMOUNT Char 
                                        Col13=SEC10_10_AMOUNT Char 
                                        Col14=SEC10_10A_AMOUNT Char 
                                        Col15=SEC10_10AA_AMOUNT Char 
                                        Col16=SEC10_13A_AMOUNT Char 
                                        Col17=SEC10_14_AMOUNT Char 
                                        Col18=SEC10_OTHERS_AMOUNT Char 
                                        Col19=BALANCE_AMOUNT Char 
                                        Col20=US_16_EA Char 
                                        Col21=US_16_TE Char 
                                        Col22=US_16_IA Char 
                                        Col23=US_16_AGGREGATE Char 
                                        Col24=INCOME_CHARGEABLE Char 
                                        Col25=INCOME_LOSS_HOUSE_PROPERTY Char 
                                        Col26=INCOME_OTHER_SOURCES Char 
                                        Col27=GROSS_TOTAL_INCOME Char 
                                        Col28=CVIA_SEC80C_DED_AMOUNT Char 
                                        Col29=CVIA_SEC80CCC_DED_AMOUNT Char 
                                        Col30=CVIA_SEC80CCD_1_DED_AMOUNT Char 
                                        Col31=CVIA_SEC80C_CCC_CCD_1_DED_AMOUNT Char 
                                        Col32=CVIA_SEC80CCD_1B_DED_AMOUNT Char 
                                        Col33=CVIA_SEC80CCD_2_DED_AMOUNT Char 
                                        Col34=CVIA_SEC80D_DED_AMOUNT Char 
                                        Col35=CVIA_SEC80E_DED_AMOUNT Char 
                                        Col36=CVIA_SEC80CCH_DED_AMOUNT Char 
                                        Col37=CVIA_SEC80CCH1_DED_AMOUNT Char 
                                        Col38=CVIA_SEC80G_DED_AMOUNT Char 
                                        Col39=CVIA_SEC80TTA_DED_AMOUNT Char 
                                        Col40=CVIA_OTH_DED_TOTAL Char 
                                        Col41=CVIA_DED_TOTAL Char 
                                        Col42=TOTAL_INCOME Char 
                                        Col43=TAX_TOTAL_INCOME Char 
                                        Col44=REBATE_US_87A_AMOUNT Char 
                                        Col45=SCHG_TOTAL_INCOME Char 
                                        Col46=ECESS_TOTAL_INCOME Char 
                                        Col47=US_89_LESS Char 
                                        Col48=TAX_PAYABLE Char 
                                        Col49=TOTAL_TDS_DEDUCTED Char 
                                        Col50=SHORTFALL_TAX Char 
                                        Col51=TAXABLE_AMOUNT Char 
                                        Col52=REPORTED_TAXABLE_AMOUNT Char 
                                        Col53=TOTAL_TAX_DEDUCTED_AMOUNT Char 
                                        Col54=PREVIOUS_TAX_DEDUCTED_TOTAL Char 
                                        Col55=TDS_US_192_2B_AMOUNT Char 
                                        Col56=TAX_DEDUCTED_HIGHER_RATE Char 
                                        Col57=TDS_SUPERANN Char 
                                        Col58=CONTRIBUTIONS_SUPERANN_YN Char 
                                        Col59=NAME_SUPERANN Char 
                                        Col60=SUPERANN_FROM_DATE Char 
                                        Col61=SUPERANN_TO_DATE Char 
                                        Col62=AMT_REPAID Char 
                                        Col63=RATE_DED Char 
                                        Col64=AMT_TAX Char 
                                        Col65=GROSS_TOTAL_INC Char 
                                        Col66=RENT_PAYMENT_YN Char 
                                        Col67=PAN_LANDLORD1 Char 
                                        Col68=NAME_LANDLORD1 Char 
                                        Col69=PAN_LANDLORD2 Char 
                                        Col70=NAME_LANDLORD2 Char 
                                        Col71=PAN_LANDLORD3 Char 
                                        Col72=NAME_LANDLORD3 Char 
                                        Col73=PAN_LANDLORD4 Char 
                                        Col74=NAME_LANDLORD4 Char 
                                        Col75=INT_PAID_YN Char 
                                        Col76=PAN_LENDER1 Char 
                                        Col77=NAME_LENDER1 Char 
                                        Col78=PAN_LENDER2 Char 
                                        Col79=NAME_LENDER2 Char 
                                        Col80=PAN_LENDER3 Char 
                                        Col81=NAME_LENDER3 Char 
                                        Col82=PAN_LENDER4 Char 
                                        Col83=NAME_LENDER4 Char ");

            #endregion
            //
            StreamWriter.Close();
            //
            if (J_Var.J_pDatabaseType == J_DatabaseType.MsAccess)
            {
                //CREATING THE IMPORT TABLE
                if (dmlService.J_IsDatabaseObjectExist(ImportTableName) == true)
                {
                    strSQL = "DROP TABLE [" + ImportTableName + "]";

                    if (dmlService.J_ExecSql(strSQL, J_SQLType.DDL) == false)
                    {
                        dmlService.J_Rollback();
                        cmnService.J_UserMessage("Import Failed!");
                        return false;
                    }
                }
            }

            //ADDED BY SHREY KEJRIWAL ON 24/05/2012
            //REPLACING DOUBLE QUOTES
            TdsMan.T_ReplaceDoubleQuotesinFile(Path.Combine(Application.StartupPath, ImportTableName + ".txt"), false);

            //QUERY TO IMPORT THE DATA FROM Char FILE
            strSQL = "SELECT * INTO [" + ImportTableName + "] FROM " +
                     "[Text; DATABASE=" + Application.StartupPath + "].[" + ImportTableName + ".txt" + "]";
            //
            if (dmlService.J_ExecSql(strSQL) == false)
            {
                dmlService.J_Rollback();
                cmnService.J_UserMessage("Import Failed!");
                return false;
            }

            return true;
        }

