        #region TxtTotalTDSDedcuted_TextChanged
        private void TxtTotalTDSDedcuted_TextChanged(object sender, EventArgs e)
        {
            if (cmnService.J_ReturnDoubleValue(txtPreviousTaxDeductedAmt.Text) == 0)
                txtTotalTaxDeductedAmt.Text = string.Format("{0:0.00}", (cmnService.J_ReturnDoubleValue(txtTotalTDSDedcuted.Text)));
            //
            Shortfall_TextChanged(sender, e);
        }
        #endregion

        #region txtDedTaxSection16ia_Enter
        private void txtDedTaxSection16ia_Enter(object sender, EventArgs e)
        {
            if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2024_25ID) //-- 2024/08/20
            {
                if (chkTaxation115BAC.Checked == true)
                {
                    if (cmnService.J_ReturnDoubleValue(txtTotalSalaryBalance.Text) >= dblStandardDeduction2425NewRegime)
                        txtDedStdDeduction.Text = string.Format("{0:0.00}", dblStandardDeduction2425NewRegime);
                    else if (cmnService.J_ReturnDoubleValue(txtTotalSalaryBalance.Text) < dblStandardDeduction2425NewRegime)
                        txtDedStdDeduction.Text = string.Format("{0:0.00}", cmnService.J_ReturnDoubleValue(txtTotalSalaryBalance.Text));
                    else
                        txtDedStdDeduction.Text = "0.00";
                }
                else
                {
                    if (cmnService.J_ReturnDoubleValue(txtTotalSalaryBalance.Text) >= dblStandardDeduction2425OldRegime)
                        txtDedStdDeduction.Text = string.Format("{0:0.00}", dblStandardDeduction2425OldRegime);
                    else if (cmnService.J_ReturnDoubleValue(txtTotalSalaryBalance.Text) < dblStandardDeduction2425OldRegime)
                        txtDedStdDeduction.Text = string.Format("{0:0.00}", cmnService.J_ReturnDoubleValue(txtTotalSalaryBalance.Text));
                    else
                        txtDedStdDeduction.Text = "0.00";
                }
            }
            else if (TDSMAN.Classes.TDSMAN.T_pFinancialYearId >= T_FinancialYearID.F2019_20ID)
            {
                if (chkTaxation115BAC.Checked == false)
                {
                    if (cmnService.J_ReturnDoubleValue(txtTotalSalaryBalance.Text) >= dblStandardDeduction1920)
                        txtDedStdDeduction.Text = string.Format("{0:0.00}", dblStandardDeduction1920); //-- 2022/08/10
                    else if (cmnService.J_ReturnDoubleValue(txtTotalSalaryBalance.Text) < dblStandardDeduction1920)
                        txtDedStdDeduction.Text = string.Format("{0:0.00}", cmnService.J_ReturnDoubleValue(txtTotalSalaryBalance.Text)); //-- 2022/08/16
                    else
                        txtDedStdDeduction.Text = "0.00";
                }
                else if (chkTaxation115BAC.Checked == false)
                    txtDedStdDeduction.Text = "0.00";
            }
            ////else
            ////{
            ////    if (cmnService.J_ReturnDoubleValue(txtTotalSalaryBalance.Text) >= dblStandardDeduction1819)
            ////        txtDedStdDeduction.Text = string.Format("{0:0.00}", dblStandardDeduction1819); //-- 2022/08/10   
            ////    else if (cmnService.J_ReturnDoubleValue(txtTotalSalaryBalance.Text) < dblStandardDeduction1819)
            ////        txtDedStdDeduction.Text = string.Format("{0:0.00}", cmnService.J_ReturnDoubleValue(txtTotalSalaryBalance.Text)); //-- 2022/08/16
            ////    else
            ////        txtDedStdDeduction.Text = "0.00";
            ////}
            //----
        }
        #endregion
    }

